    ["Avec l'argent de la guilde d'abord"] = "Zuerst mit dem Gildengold",
    ["Avec un son"] = "Mit Ton",
    ["Avec une petite pièce sur ce qui serait vendu."] = "Mit einer kleinen Münze auf dem, was verkauft würde.",
    ["Bande passante"] = "Bandbreite",
    ["Bandeau à l'écran"] = "Banner auf dem Bildschirm",
    ["Barre"] = "Leiste",
    ["Barre d'infos"] = "Infoleiste",
    ["Barre d'infos à côté de l'icône"] = "Infoleiste neben dem Symbol",
    ["Barre de coups blancs"] = "Leiste für normale Angriffe",
    ["Barre de coups blancs : le minuteur de ton attaque automatique, pour placer tes coups au bon moment."] = "Schwunganzeige: der Timer deines automatischen Angriffs, damit du deine Schläge im richtigen Moment setzt.",
    ["Barre de coups blancs, rappel de buffs, fenêtre de menace, mana de ton healer et contrôles des mobs."] = "Schwunganzeige, Buff-Erinnerung, Bedrohungsfenster, Mana deines Heilers und Gegnerkontrolle.",
    ["Barres d'action"] = "Aktionsleisten",
    ["Barres d'incantation : une couleur à part quand ton interruption est prête."] = "Zauberleisten: eine eigene Farbe, wenn deine Unterbrechung bereit ist.",
    ["Barres d'incantation Platyplus"] = "Platyplus-Zauberleisten",
    ["Besoin"] = "Bedarf",
    ["Besoin pour sa 2e spécialisation"] = "Bedarf für 2. Spezialisierung",
    ["Bientôt : boss, butin et quêtes pas encore connus."] = "Bald: Bosse, Beute und Quests noch nicht bekannt.",
    ["Bienvenue"] = "Willkommen",
    ["Bienvenue dans %s"] = "Willkommen bei %s",
    ["Bijou"] = "Schmuckstück",
    ["Bilan"] = "Bilanz",
    ["Blizzard exige un clic ou une touche pour chaque mise en vente : aucun addon ne peut tout poster seul. Choisis une touche dans /pp > Vente > Hôtel des ventes, ou crée une macro « /click %s »."] = "Blizzard verlangt für jedes Einstellen einen Klick oder eine Taste: kein Addon kann alles allein einstellen. Wähle eine Taste unter /pp > Verkauf > Auktionshaus oder erstelle ein Makro »/click %s«.",
    ["Boisson choisie hors combat, puis la potion de mana prise en combat. Mis à jour quand tes sacs changent."] = "Getränk, das außerhalb des Kampfes gewählt wird, dann der im Kampf genutzte Manatrank. Wird aktualisiert, wenn sich deine Taschen ändern.",
    ["Bon à savoir"] = "Gut zu wissen",
    ["Bonus de repos"] = "Ruhebonus",
    ["Bord de couleur sur ta cible"] = "Farbiger Rand um dein Ziel",
    ["Boss précédent"] = "Vorheriger Boss",
    ["Boss suivant"] = "Nächster Boss",
    ["Bouton « copier le chat »"] = "Schaltfläche „Chat kopieren“",
    ["Buffs de tes alliés : %s - %s"] = "Buffs deiner Verbündeten: %s - %s",
    ["Buffs que mes alliés peuvent me donner"] = "Buffs, die meine Verbündeten mir geben können",
    ["Buffs que mon groupe peut me donner"] = "Buffs, die meine Gruppe mir geben kann",
    ["Buffs à demander"] = "Zu erbittende Buffs",
    ["Buffs à demander — glisse-moi"] = "Zu erbittende Buffs - zieh mich",
    ["Butin"] = "Beute",
    ["Bénéfice"] = "Gewinn",
    ["C'est parti"] = "Los geht's",
    ["C, U et les autres touches du jeu ouvrent le bon onglet ; la même touche ou Échap la referme."] = "C, U und die anderen Spieltasten öffnen den passenden Reiter; dieselbe Taste oder Esc schließt ihn wieder.",
    ["CONSEILLÉ"] = "EMPFOHLEN",
    ["CVars utiles (SoftTarget*, autoLoot*)"] = "Nützliche CVars (SoftTarget*, autoLoot*)",
    ["Cache la fenêtre de dialogue animée (« tête parlante ») qui apparaît en haut de l'écran."] = "Verbirgt das animierte Dialogfenster („sprechender Kopf“), das oben auf dem Bildschirm erscheint.",
    ["Cache les barres d'expérience et de réputation de Blizzard. L'XP reste lisible dans la barre d'infos de Platyplus (pourcentage, XP par heure, temps avant le niveau). Coupé, les barres reviennent tout de suite."] = "Verbirgt die Erfahrungs- und Rufleisten von Blizzard. Die EP bleiben in der Platyplus-Infoleiste lesbar (Prozent, EP pro Stunde, Zeit bis zur nächsten Stufe). Ausgeschaltet kommen die Leisten sofort zurück.",
    ["Cache les cartes pour cette quête ; la fenêtre de Blizzard reste ouverte."] = "Verbirgt die Karten für diese Quest; das Blizzard-Fenster bleibt offen.",
    ["Cache les messages d'erreur rouges qui s'affichent au milieu de l'écran."] = "Verbirgt die roten Fehlermeldungen in der Bildschirmmitte.",
    ["Cache les mobs que tu tiens déjà ; la fenêtre ne montre que ce qui demande ton attention."] = "Verbirgt die Gegner, die du schon hältst; das Fenster zeigt nur, was deine Aufmerksamkeit braucht.",
    ["Cacher les icônes de Questie"] = "Questie-Symbole ausblenden",
    ["Cachée, tu ouvres toujours les options avec /pp."] = "Auch wenn es versteckt ist, öffnest du die Optionen immer mit /pp.",
    ["Cadavres avec du butin"] = "Leichen mit Beute",
    ["Cadre"] = "Rahmen",
    ["Cadre Platyplus"] = "Platyplus-Rahmen",
    ["Canal"] = "Kanal",
    ["Canal %d"] = "Kanal %d",
    ["Canaux"] = "Kanäle",
    ["Caractéristiques"] = "Werte",
    ["Carré"] = "Quadrat",
    ["Carte"] = "Karte",
    ["Cases par ligne"] = "Felder pro Zeile",
    ["Ce joueur avait déjà lancé les dés : ce jet ne compte pas."] = "Dieser Spieler hatte schon gewürfelt: Dieser Wurf zählt nicht.",
    ["Ce qu'il faut faire s'affiche en grand près de ton personnage, avec la touche à presser."] = "Was zu tun ist, erscheint groß bei deinem Charakter, mit der Taste, die du drücken musst.",
    ["Ce qu'un mob peut te faire subir, avant de le taper."] = "Was ein Gegner dir antun kann, bevor du ihn angreifst.",
    ["Ce que fait la touche"] = "Was die Taste bewirkt",
    ["Ce que le jeu fait réellement quand tu appuies sur ta touche, en ce moment. Hors dialogue c'est l'interaction rapide ; pendant un dialogue de PNJ c'est l'avance du dialogue."] = "Was das Spiel tatsächlich tut, wenn du jetzt deine Taste drückst. Außerhalb von Dialogen ist es die Schnellinteraktion; in einem NPC-Dialog führt es den Dialog weiter.",
    ["Ce que te disent les PNJ dans une fenêtre Platyplus : discussion, quête proposée, objets à rapporter, récompenses. Texte en grand, déplaçable."] = "Was NPCs dir sagen, in einem Platyplus-Fenster: Gespräch, angebotene Quest, mitzubringende Gegenstände, Belohnungen. Großer Text, verschiebbar.",
    ["Ce que tu gagnes défile à côté de ton personnage : butin, achats, objets fabriqués, récompenses de quête."] = "Was du erhältst, läuft neben deinem Charakter vorbei: Beute, Einkäufe, hergestellte Gegenstände, Questbelohnungen.",
    ["Ce que tu ouvres avec C : équipement, caractéristiques, réputation, compétences, JcJ, dans une fenêtre Platyplus à onglets."] = "Was du mit C öffnest: Ausrüstung, Werte, Ruf, Fertigkeiten, PvP, in einem Platyplus-Fenster mit Reitern.",
    ["Ce que tu ramasses, fabriques, achètes ou vends s'affiche près de ton personnage, les objets identiques se cumulent, puis tout s'estompe."] = "Was du erbeutest, herstellst, kaufst oder verkaufst, erscheint nahe deiner Figur, gleiche Gegenstände addieren sich, dann blendet alles aus.",
    ["Ce qui serait vendu chez un marchand avec les réglages actuels. Mis à jour à l'ouverture de l'onglet et à chaque changement de réglage."] = "Was bei einem Händler mit den aktuellen Einstellungen verkauft würde. Wird beim Öffnen des Reiters und bei jeder Einstellungsänderung aktualisiert.",
    ["Ce réglage n'existe pas sur ton client."] = "Diese Einstellung gibt es auf deinem Client nicht.",
    ["Ces objets sont toujours épargnés, quelle que soit leur qualité."] = "Diese Gegenstände werden immer verschont, egal welcher Qualität.",
    ["Ces objets sont vendus à chaque marchand, même s'ils ne sont pas gris."] = "Diese Gegenstände werden bei jedem Händler verkauft, auch wenn sie nicht grau sind.",
    ["Ceux qui ne marchent qu'après un événement : Fulgurance après une esquive, Exécution sous 20 % de vie."] = "Die, die erst nach einem Ereignis funktionieren: Überwältigen nach einem Ausweichen, Hinrichten unter 20 % Leben.",
    ["Changer la touche"] = "Taste ändern",
    ["Chaque donjon : ses boss et leur butin, ses quêtes (où les prendre, les suites de quêtes, les récompenses), son plan et le chemin jusqu'à l'entrée. Ouvrir : /dj, /pp donjons, le menu de l'icône Platyplus, ou la touche de l'addon DungeonJournal."] = "Jeder Dungeon: seine Bosse und deren Beute, seine Quests (wo man sie annimmt, Questreihen, Belohnungen), seine Karte und der Weg zum Eingang. Öffnen: /dj, /pp donjons, das Menü des Platyplus-Symbols oder die Taste des Addons DungeonJournal.",
    ["Chaque donjon : ses boss et leur butin, ses quêtes (où les prendre, les suites de quêtes, les récompenses), son plan et le chemin jusqu'à l'entrée. Touche : Raccourcis > Journal des donjons. Aussi : /dj, /pp donjons, ou le menu de l'icône Platyplus."] = "Jeder Dungeon: seine Bosse und deren Beute, seine Quests (wo man sie annimmt, Questreihen, Belohnungen), seine Karte und der Weg zum Eingang. Taste: Tastenbelegung > Dungeonjournal. Außerdem: /dj, /pp donjons oder das Menü des Platyplus-Symbols.",
    ["Chaque objet gagné s'affiche quelques secondes à côté de ton personnage, avec sa quantité."] = "Jeder erhaltene Gegenstand wird einige Sekunden neben deinem Charakter angezeigt, mit seiner Anzahl.",
    ["Chaque objet vendu apparaît dans le flux avec son prix, puis le total encaissé."] = "Jeder verkaufte Gegenstand erscheint mit seinem Preis im Feed, dann die Gesamteinnahme.",
    ["Chargement…"] = "Lädt …",
    ["Charges arcaniques"] = "Arkane Aufladungen",
    ["Chat"] = "Chat",
    ["Chemise"] = "Hemd",
    ["Chercher"] = "Suchen",
    ["Chercher les prix dès l'ouverture"] = "Preise sofort beim Öffnen suchen",
    ["Chercher…"] = "Suchen …",
    ["Chez un marchand, tous tes objets gris sont vendus."] = "Bei einem Händler werden alle deine grauen Gegenstände verkauft.",
    ["Chi"] = "Chi",
    ["Chiffres sur les barres de vie et de ressource"] = "Zahlen auf Lebens- und Ressourcenleisten",
    ["Chiffres sur les temps de recharge"] = "Zahlen bei Abklingzeiten",
    ["Choisir aussi la 1re option de dialogue"] = "Auch die 1. Dialogoption wählen",
    ["Choisis les infos affichées dans l'onglet Icône & infos."] = "Wähle die angezeigten Infos im Reiter Symbol & Infos.",
    ["Choisis ta base"] = "Wähle deine Grundlage",
    ["Choisis ta récompense"] = "Wähle deine Belohnung",
    ["Choisis un objet (clic ou touche 1, 2, 3...), puis rends la quête :"] = "Wähle einen Gegenstand (Klick oder Taste 1, 2, 3 ...), dann gib die Quest ab:",
    ["Choisis une carte"] = "Wähle eine Karte",
    ["Choisis une récompense"] = "Wähle eine Belohnung",
    ["Chuchote"] = "Flüstern",
    ["Cible ton healer, puis clique : la barre suit ce joueur tant qu'il est dans ton groupe, même si le groupe ne lui a pas donné le rôle de soigneur (aussi : /pp healer cible)."] = "Wähle deinen Heiler als Ziel und klicke dann: Die Leiste folgt diesem Spieler, solange er in deiner Gruppe ist, auch wenn die Gruppe ihm nicht die Heilerrolle gegeben hat (auch: /pp healer cible).",
    ["Cibler l'ennemi qui est devant moi"] = "Den Feind vor mir anvisieren",
    ["Clic"] = "Klick",
    ["Clic : choisir · double-clic : choisir et rendre la quête"] = "Klick: wählen · Doppelklick: wählen und Quest abgeben",
    ["Clic : cocher pour le mettre en vente (retenu pour les prochaines fois)"] = "Klick: anhaken, um es einzustellen (wird für das nächste Mal gemerkt)",
    ["Clic : copier ce message"] = "Klick: diese Nachricht kopieren",
    ["Clic : décocher (il ne sera plus mis en vente)"] = "Klick: abhaken (es wird nicht mehr eingestellt)",
    ["Clic : ouvrir la fiche du personnage"] = "Klick: Charakterfenster öffnen",
    ["Clic droit : ne plus jamais le proposer"] = "Rechtsklick: nie wieder vorschlagen",
    ["Clic droit pour valider - les lignes descendent"] = "Rechtsklick zum Bestätigen - die Zeilen laufen nach unten",
    ["Clic droit pour valider - les lignes montent"] = "Rechtsklick zum Bestätigen - die Zeilen laufen nach oben",
    ["Clic droit sur le libellé : valeur par défaut."] = "Rechtsklick auf die Beschriftung: Standardwert.",
    ["Clic droit sur un paladin, un prêtre, un mage… : « Demander un buff » lui chuchote ta demande."] = "Rechtsklick auf einen Paladin, Priester, Magier ...: „Um einen Buff bitten“ flüstert ihm deine Anfrage zu.",
    ["Clic gauche : les options. Clic droit : un menu pour allumer ou couper les fonctions. Glisse-la pour la déplacer."] = "Linksklick: die Optionen. Rechtsklick: ein Menü zum Ein- und Ausschalten der Funktionen. Zieh es, um es zu verschieben.",
    ["Clic sur la grande pastille : choisir une couleur. Clic droit : défaut."] = "Klick auf das große Farbfeld: Farbe wählen. Rechtsklick: Standard.",
    ["Clignote quand un mob t'échappe"] = "Blinkt, wenn dir ein Gegner entkommt",
    ["Clignoter quand un mob m'échappe"] = "Blinken, wenn mir ein Gegner entkommt",
    ["Clique encore pour confirmer"] = "Klicke noch einmal zum Bestätigen",
    ["Clique encore pour recharger"] = "Klicke noch einmal zum Neuladen",
    ["Clique encore pour remplacer tes réglages actuels par ce mode."] = "Klick noch einmal, um deine aktuellen Einstellungen durch diesen Modus zu ersetzen.",
    ["Clique encore pour vider"] = "Klicke noch einmal zum Leeren",
    ["Clique ici pour changer de touche"] = "Hier klicken, um die Taste zu ändern",
    ["Clique ici puis appuie sur la touche voulue (avec Maj, Ctrl ou Alt si tu veux). Pour un bouton de souris (molette, boutons latéraux), clique dans ce cadre avec ce bouton. Échap annule."] = "Klicke hier und drücke dann die gewünschte Taste (auf Wunsch mit Umschalt, Strg oder Alt). Für eine Maustaste (Rad, Seitentasten) klicke mit dieser Taste in diesen Rahmen. Esc bricht ab.",
    ["Clique sur « %s » pour avoir Platyplus dans la langue de ton jeu."] = "Klick auf „%s“, um Platyplus in der Sprache deines Spiels zu haben.",
    ["Clique sur « Actualiser l'aperçu » pour voir ce qui serait vendu."] = "Klicke auf „Vorschau aktualisieren“, um zu sehen, was verkauft würde.",
    ["Coche les objets à vendre"] = "Hake die zu verkaufenden Gegenstände an",
    ["Coche les objets à vendre (clic sur la ligne) : tes choix sont retenus pour la prochaine fois."] = "Hake die zu verkaufenden Gegenstände an (Klick auf die Zeile): deine Auswahl wird für das nächste Mal gemerkt.",
    ["Coché : le nom en couleur puis le texte, sans bulle ; les messages qui se suivent du même joueur (moins d'une minute) se resserrent, sans répéter l'heure. Clic sur l'heure ou clic droit sur le message : copier. Coupé : une ligne brute par message (« 15:27 [Guilde] Bob : salut »)."] = "Aktiviert: Name in Farbe, dann der Text, ohne Blase; aufeinanderfolgende Nachrichten desselben Spielers (unter einer Minute) rücken zusammen, ohne die Uhrzeit zu wiederholen. Klick auf die Uhrzeit oder Rechtsklick auf die Nachricht: kopieren. Aus: eine Rohzeile pro Nachricht („15:27 [Gilde] Bob: hallo“).",
    ["Combat"] = "Kampf",
    ["Combien de lignes le flux peut afficher en même temps. Les plus anciennes disparaissent en premier."] = "Wie viele Zeilen der Feed gleichzeitig zeigen kann. Die ältesten verschwinden zuerst.",
    ["Commandes"] = "Befehle",
    ["Comme Threat Plates : qui tape qui, d'un coup d'œil, et un look à ton goût."] = "Wie bei Threat Plates: Wer greift wen an, auf einen Blick, und ein Aussehen nach deinem Geschmack.",
    ["Comme le chat du jeu : vert pour la guilde, bleu pour le groupe..."] = "Wie im Spielchat: grün für die Gilde, blau für die Gruppe ...",
    ["Comme le jeu"] = "Wie im Spiel",
    ["Comme ton équipement"] = "Wie deine Ausrüstung",
    ["Commencer la visite"] = "Rundgang starten",
    ["Commun"] = "Gewöhnlich",
    ["Complet"] = "Komplett",
    ["Composants"] = "Komponenten",
    ["Compétences"] = "Fertigkeiten",
    ["Compétences indisponibles sur ce client."] = "Fertigkeiten auf diesem Client nicht verfügbar.",
    ["Confirmer : %s"] = "Bestätigen: %s",
    ["Confirmer seul les objets « lié quand ramassé »"] = "„Beim Aufheben gebunden“-Gegenstände selbst bestätigen",
    ["Confort"] = "Komfort",
    ["Contrôle l'esprit"] = "Gedankenkontrolle",
    ["Contrôles des mobs"] = "Gegnerkontrolle",
    ["Coordonnées"] = "Koordinaten",
    ["Copie"] = "Kopie",
    ["Copier le chat"] = "Chat kopieren",
    ["Copier le message"] = "Nachricht kopieren",
    ["Couleur de la progression"] = "Fortschrittsfarbe",
    ["Couleur du bord"] = "Randfarbe",
    ["Couleur du clignotement"] = "Blinkfarbe",
    ["Couleur du fond"] = "Hintergrundfarbe",
    ["Couleur selon qu'on peut l'interrompre, et le temps restant."] = "Farbe je nachdem, ob sie unterbrochen werden kann, und die Restzeit.",
    ["Couleur « autre tank »"] = "Farbe „Anderer Tank“",
    ["Couleur « interruption prête »"] = "Farbe „Unterbrechung bereit“",
    ["Couleurs"] = "Farben",
    ["Couleurs de menace"] = "Bedrohungsfarben",
    ["Coup blanc"] = "Weißer Treffer",
    ["Coupe l'option « icônes d'objectif sur les plates » de Questie. Décoche pour la rallumer."] = "Schaltet die Questie-Option „Zielsymbole an Namensplaketten“ aus. Abwählen, um sie wieder einzuschalten.",
    ["Coupé : le cadre du jeu (large, avec une ombre en bas à droite) revient, coins carrés."] = "Aus: Der Spielrahmen (breit, mit Schatten unten rechts) kommt zurück, eckige Ecken.",
    ["Coupé : le texte des messages est en clair, seul le [canal] prend sa couleur. Coché : le texte aussi, comme dans le chat du jeu."] = "Aus: Der Nachrichtentext ist schlicht, nur der [Kanal] bekommt seine Farbe. An: auch der Text, wie im Spielchat.",
    ["Coupé, il ne reste que l'icône (et le nom si tu le gardes) : tu connais déjà ta touche."] = "Ausgeschaltet bleibt nur das Symbol (und der Name, wenn du ihn behältst): Du kennst deine Taste ja schon.",
    ["Coupés : les alertes de combat, la barre de coups blancs, le butin affiché à l'écran, la fenêtre de menace, la barre d'infos, les plates colorées, les contrôles des mobs dans l'infobulle, le niveau d'objet et les messages d'erreur rouges. Restent : la touche (tu choisis toi-même tes réponses aux PNJ), le loot instantané, la vente, les grandes fenêtres de quête avec leur histoire dépliée, la caméra plus loin."] = "Aus: Kampfwarnungen, die Leiste für normale Angriffe, die Beute auf dem Bildschirm, das Bedrohungsfenster, die Infoleiste, die farbigen Plaketten, die Kontrolleffekte der Mobs im Tooltip, die Gegenstandsstufe und die roten Fehlermeldungen. Bleiben: die Taste (du wählst deine Antworten an NPCs selbst), Sofortbeute, der Verkauf, die großen Questfenster mit ausgeklappter Geschichte, die weiter entfernte Kamera.",
    ["Coût : %s"] = "Kosten: %s",
    ["Coût et bénéfice des recettes"] = "Kosten und Gewinn von Rezepten",
    ["Cri de guerre"] = "Schlachtruf",
    ["Cri de guerre en combat"] = "Schlachtruf im Kampf",
    ["Cri de guerre manquant"] = "Schlachtruf fehlt",
    ["Ctrl"] = "Strg",
    ["Ctrl+C : traduire   ·   Échap : fermer"] = "Strg+C: übersetzen   ·   Esc: schließen",
    ["Ctrl+C pour copier · Échap pour fermer"] = "Strg+C zum Kopieren · Esc zum Schließen",
    ["Cupidité"] = "Gier",
    ["D'autres onglets t'attendent : Confort (invitations, duels, invocations), Réglages du jeu (réglages conseillés en un clic) et Avancé (langue de Platyplus, remise à zéro)."] = "Weitere Reiter warten auf dich: Komfort (Einladungen, Duelle, Beschwörungen), Spieleinstellungen (empfohlene Einstellungen mit einem Klick) und Erweitert (Sprache von Platyplus, Zurücksetzen).",
    ["DURABILITÉ"] = "HALTBARKEIT",
    ["Danger"] = "Gefahr",
    ["Dans l'infobulle des mobs"] = "Im Gegner-Tooltip",
    ["Dans la zone de saisie, les flèches haut et bas remontent les messages et commandes que tu as déjà envoyés (les 32 derniers), même après un /reload. Coupé : il faut Alt + flèches, comme dans le jeu de base."] = "Im Eingabefeld rufen die Pfeiltasten hoch und runter die schon gesendeten Nachrichten und Befehle zurück (die letzten 32), auch nach einem /reload. Aus: Du brauchst Alt + Pfeiltasten, wie im Basisspiel.",
    ["Dans le même onglet, deux touches de plus pour manger et boire le meilleur de tes sacs (une potion en combat)."] = "Im selben Reiter gibt es zwei weitere Tasten, um das Beste aus deinen Taschen zu essen und zu trinken (im Kampf einen Trank).",
    ["Dans les options, survole un réglage pour lire son explication. Clic droit sur un curseur : il revient à sa valeur par défaut."] = "Fahr in den Optionen über eine Einstellung, um ihre Erklärung zu lesen. Rechtsklick auf einen Regler: Er springt auf seinen Standardwert zurück.",
    ["Dans tous les canaux."] = "In allen Kanälen.",
    ["Dans un dialogue, la même touche fait défiler le texte, accepte la quête, puis la rend."] = "In einem Dialog blättert dieselbe Taste durch den Text, nimmt die Quest an und gibt sie dann ab.",
    ["De coins carrés (0) à des bouts bien ronds (4)."] = "Von eckigen Ecken (0) bis zu schön runden Enden (4).",
    ["De l'eau"] = "Wasser",
    ["De la nourriture"] = "Nahrung",
    ["De petits éclats dorés sur la plante la plus proche."] = "Kleine goldene Funken auf der nächsten Pflanze.",
    ["Demande les prix dès que tu ouvres l'HDV : une seule recherche groupée pour tes marchandises (minerais, herbes, tissus...), puis une par pièce d'équipement. Tu peux mettre en vente pendant que la recherche continue. Coupé : clique « Rechercher à nouveau » dans le panneau."] = "Fragt die Preise ab, sobald du das Auktionshaus öffnest: eine gebündelte Suche für deine Waren (Erz, Kräuter, Stoffe ...), dann eine pro Ausrüstungsteil. Du kannst einstellen, während die Suche weiterläuft. Aus: Klicke im Panel auf „Erneut suchen“.",
    ["Demander un buff"] = "Einen Buff erbitten",
    ["Demander un buff au clic droit"] = "Per Rechtsklick um einen Buff bitten",
    ["Des alertes de combat lisibles"] = "Lesbare Kampfwarnungen",
    ["Des fenêtres plus claires"] = "Übersichtlichere Fenster",
    ["Des infos utiles à côté de l'icône, mises à jour sans rien coûter en jeu."] = "Nützliche Infos neben dem Symbol, ohne Leistungskosten im Spiel aktualisiert.",
    ["Deux touches qui prennent le meilleur de tes sacs : à manger ou à boire hors combat, une potion en combat."] = "Zwei Tasten, die das Beste aus deinen Taschen nehmen: außerhalb des Kampfes essen oder trinken, im Kampf einen Trank.",
    ["Diagnostic"] = "Diagnose",
    ["Diagnostic, commandes et réinitialisation."] = "Diagnose, Befehle und Zurücksetzen.",
    ["Distance maximale, en mètres, de la cible d'interaction automatique (réglage du jeu « SoftTargetInteractRange »). Une valeur trop grande peut te faire cibler des objets lointains. Expérimental."] = "Maximale Entfernung in Metern des automatischen Interaktionsziels (Spieleinstellung „SoftTargetInteractRange“). Ein zu großer Wert kann dazu führen, dass du weit entfernte Objekte anvisierst. Experimentell.",
    ["Dit dans le chat si le journal du chat est allumé."] = "Sagt im Chat, ob das Chatprotokoll an ist.",
    ["Domicile"] = "Heimat",
    ["Domicile : discussion, hôtel des ventes. Monde : combat et autres joueurs. Vert jusqu'à 100 ms, orange jusqu'à 250 ms, rouge au-delà."] = "Heimat: Unterhaltung, Auktionshaus. Welt: Kampf und andere Spieler. Grün bis 100 ms, orange bis 250 ms, rot darüber.",
    ["Donjons"] = "Dungeons",
    ["Double-clic"] = "Doppelklick",
    ["Douleur"] = "Schmerz",
    ["Doux"] = "Sanft",
    ["DungeonJournal %s, par Exehn : le journal, ses données (boss, butin, quêtes, plans, routes) et ses images. Platyplus l'intègre tel quel (dev/make_dungeonjournal.py) et y ajoute la liste de gauche, « À ton niveau » et son style. Tes réglages, favoris et progression du journal sont gardés par Platyplus."] = "DungeonJournal %s von Exehn: das Journal, seine Daten (Bosse, Beute, Quests, Karten, Routen) und seine Bilder. Platyplus bindet es unverändert ein (dev/make_dungeonjournal.py) und fügt die linke Liste, „Auf deiner Stufe“ und seinen Stil hinzu. Deine Journaleinstellungen, Favoriten und dein Fortschritt werden von Platyplus gespeichert.",
    ["DungeonJournal, par Exehn : le journal, ses données (boss, butin, quêtes, plans, routes) et ses images viennent de son addon, installé à part ; Platyplus n'en embarque rien. Platyplus y ajoute la liste de gauche, « À ton niveau » et son style en passant derrière lui, sans rien modifier dans l'addon : éteins les trois réglages (puis /reload) et il retrouve son look d'origine."] = "DungeonJournal, von Exehn: Das Journal, seine Daten (Bosse, Beute, Quests, Karten, Routen) und seine Bilder stammen aus seinem separat installierten Addon; Platyplus liefert nichts davon mit. Platyplus ergänzt die Liste links, „Auf deiner Stufe“ und seinen Stil, indem es nach ihm läuft, ohne etwas am Addon zu ändern: Schalte die drei Einstellungen aus (dann /reload), und es erhält sein ursprüngliches Aussehen zurück.",
    ["Dura"] = "Haltb.",
    ["Durabilité"] = "Haltbarkeit",
    ["Durée"] = "Dauer",
    ["Durée d'affichage"] = "Anzeigedauer",
    ["Durée des ventes"] = "Verkaufsdauer",
    ["Dès qu'un dialogue de quête s'ouvre, Platyplus accepte la quête ou la rend tout seul, sans touche. Si elle propose plusieurs récompenses, il attend que tu en choisisses une. Maintiens Maj en ouvrant le dialogue pour lire tranquillement."] = "Sobald ein Questdialog aufgeht, nimmt Platyplus die Quest von selbst an oder gibt sie ab, ohne Taste. Bietet sie mehrere Belohnungen, wartet es, bis du eine wählst. Halte Umschalt beim Öffnen des Dialogs, um in Ruhe zu lesen.",
    ["Dès qu'un objet est mis aux dés dans ton groupe."] = "Sobald ein Gegenstand in deiner Gruppe zum Würfeln freigegeben wird.",
    ["Déclarer la guerre"] = "Krieg erklären",
    ["Décoche pour déplacer la fenêtre en tirant son bandeau."] = "Abwählen, um das Fenster am Titelbalken zu verschieben.",
    ["Décoché, la fenêtre reste affichée en permanence."] = "Abgewählt bleibt das Fenster ständig sichtbar.",
    ["Dégradé Platyplus"] = "Platyplus-Farbverlauf",
    ["Départage /roll"] = "/roll-Stichentscheid",
    ["Déplacer"] = "Verschieben",
    ["Dépose ici un objet de tes sacs : il ne sera jamais vendu automatiquement."] = "Leg hier einen Gegenstand aus deinen Taschen ab: Er wird nie automatisch verkauft.",
    ["Dépose ici un objet de tes sacs : il sera vendu à chaque visite chez un marchand."] = "Leg hier einen Gegenstand aus deinen Taschen ab: Er wird bei jedem Händlerbesuch verkauft.",
    ["Dés lancés à la main"] = "Von Hand geworfene Würfel",
    ["Désarme"] = "Entwaffnet",
    ["Détail"] = "Detail",
    ["Déverrouille l'alerte pour la glisser où tu veux ; reclique (ou clic droit dessus) pour la verrouiller."] = "Entsperrt die Warnung, damit du sie beliebig verschieben kannst; erneut klicken (oder Rechtsklick darauf) sperrt sie.",
    ["Déverrouille la barre pour la glisser où tu veux ; reclique (ou clic droit sur la barre) pour la verrouiller."] = "Entsperrt die Leiste, damit du sie beliebig verschieben kannst; erneut klicken (oder Rechtsklick auf die Leiste) sperrt sie.",
    ["Déverrouille la barre pour la glisser où tu veux ; reclique pour la verrouiller."] = "Entsperrt die Leiste, damit du sie beliebig verschieben kannst; erneut klicken sperrt sie.",
    ["Déverrouille la rangée des buffs à demander pour la glisser où tu veux ; reclique (ou clic droit dessus) pour la verrouiller."] = "Entsperrt die Reihe der erbetenen Buffs, damit du sie beliebig verschieben kannst; erneut klicken (oder Rechtsklick darauf) sperrt sie.",
    ["Effacer"] = "Löschen",
    ["Effacer l'historique"] = "Verlauf löschen",
    ["Elle apparaît au début du combat et disparaît en fondu 3 s après la fin."] = "Sie erscheint zu Kampfbeginn und blendet 3 s nach dem Ende aus.",
    ["Emplacement vide"] = "Leerer Platz",
    ["Emplacements libres restants"] = "Verbleibende freie Plätze",
    ["Empêche de déplacer l'icône par erreur. Déverrouillée, glisse-la où tu veux."] = "Verhindert, dass du das Symbol versehentlich verschiebst. Entsperrt kannst du es beliebig ziehen.",
    ["En combat ; dorée quand Frappe héroïque attend le prochain coup."] = "Im Kampf; golden, wenn Heldenhafter Stoß auf den nächsten Treffer wartet.",
    ["En combat seulement : si tu n'as pas ton Cri de guerre, son icône apparaît en grand avec la touche à presser (« Cri de guerre manquant »), bleutée tant que tu n'as pas assez de rage. Elle disparaît dès que tu cries. Il faut que le Cri de guerre soit rangé sur tes barres. Fonctionne même si l'alerte de proc est coupée."] = "Nur im Kampf: Fehlt dein Schlachtruf, erscheint sein Symbol groß mit der zu drückenden Taste („Schlachtruf fehlt“), bläulich, solange dir die Wut fehlt. Es verschwindet, sobald du rufst. Der Schlachtruf muss auf deinen Leisten liegen. Funktioniert auch bei ausgeschalteter Proc-Warnung.",
    ["En combat, la barre de vie de chaque mob (sa « plate ») prend la couleur de la situation."] = "Im Kampf nimmt die Lebensleiste jedes Gegners (seine „Plakette“) die Farbe der Lage an.",
    ["En combat, la barre de vie de chaque mob prend une couleur selon sa cible :\n|cff33d14dvert|r : il te tape (tank) — ou il t'ignore (DPS/soins) ;\n|cffff9e1aorange|r : ça se joue, quelqu'un est sur le point de prendre ou de perdre l'aggro ;\n|cfff22e26rouge|r : il tape un allié (tank) — ou il te tape (DPS/soins) ;\n|cff409ef9bleu|r : un autre tank du groupe le tient.\nPlus tout le look ci-dessous. Les plates s'affichent avec la touche V."] = "Im Kampf nimmt die Lebensleiste jedes Gegners eine Farbe je nach seinem Ziel an:\n|cff33d14dgrün|r: er greift dich an (Tank) – oder ignoriert dich (Schaden/Heilung);\n|cffff9e1aorange|r: es steht auf der Kippe, jemand nimmt oder verliert gleich die Aggro;\n|cfff22e26rot|r: er greift einen Verbündeten an (Tank) – oder dich (Schaden/Heilung);\n|cff409ef9blau|r: ein anderer Tank der Gruppe hält ihn.\nDazu das ganze Aussehen unten. Die Plaketten erscheinen mit der Taste V.",
    ["En combat, ton Cri de guerre s'il te manque. Hors combat, ce que tes alliés peuvent te donner et que tu n'as pas, et un clic droit pour le leur demander."] = "Im Kampf dein Schlachtruf, falls er fehlt. Außerhalb des Kampfes das, was deine Verbündeten dir geben können und du nicht hast, und ein Rechtsklick, um sie darum zu bitten.",
    ["En combat. Tank / DPS : les rôles s'inversent tout seuls."] = "Im Kampf. Tank / Schaden: Die Rollen tauschen sich von selbst.",
    ["En donjon ou en raid, une fenêtre suit chaque objet mis aux dés : le choix de chaque joueur (Besoin, Cupidité, Passe), son dé, sa classe, qui mène et qui gagne."] = "In einem Dungeon oder Schlachtzug folgt ein Fenster jedem zum Würfeln freigegebenen Gegenstand: die Wahl jedes Spielers (Bedarf, Gier, Passen), sein Wurf, seine Klasse, wer führt und wer gewinnt.",
    ["En groupe avec deux tanks : un mob tenu par l'autre tank n'est pas « danger » (pas ton problème)."] = "In einer Gruppe mit zwei Tanks: Ein vom anderen Tank gehaltener Gegner ist keine „Gefahr“ (nicht dein Problem).",
    ["En groupe, elle s'ouvre quand un objet est mis aux dés et montre le choix et le dé de chaque joueur."] = "In der Gruppe öffnet sie sich, wenn ein Gegenstand zum Würfeln freigegeben wird, und zeigt die Wahl und den Wurf jedes Spielers.",
    ["En groupe, une fenêtre de menace liste chaque mob du combat et qui il attaque."] = "In der Gruppe listet ein Bedrohungsfenster jeden Gegner im Kampf und wen er angreift.",
    ["En groupe, une fenêtre suit les jets de dés : qui fait Besoin ou Cupidité, et qui gagne."] = "In der Gruppe verfolgt ein Fenster die Würfe: wer Bedarf oder Gier wählt und wer gewinnt.",
    ["En guerre : tu peux attaquer ses membres."] = "Im Krieg: Du kannst seine Mitglieder angreifen.",
    ["En rouge à %d places libres ou moins."] = "Rot bei %d freien Plätzen oder weniger.",
    ["Espace"] = "Leertaste",
    ["Essence"] = "Essenz",
    ["Et aussi :"] = "Und außerdem:",
    ["Et celle de réputation, en bas de l'écran."] = "Und die Ruf-Leiste unten am Bildschirm.",
    ["Ex. un chaman kobold lance Éclair : la barre est jaune (interruptible), bleue si ta Volée de coups est prête, grise s'il est protégé (bouclier : rien à faire)."] = "Bsp.: Ein Kobold-Schamane wirkt Blitzschlag: Die Leiste ist gelb (unterbrechbar), blau, wenn dein Zuschlagen bereit ist, grau, wenn er geschützt ist (Schild: nichts zu tun).",
    ["Ex. « 3/8 » et un ! à côté de la barre d'un loup qu'il te reste à tuer."] = "Bsp.: „3/8“ und ein ! neben der Leiste eines Wolfs, den du noch töten musst.",
    ["Ex. « Coup de pied rapide — Étourdit 2 s   toutes les 5-9 s »."] = "Bsp.: „Tritt“ betäubt 2 s   alle 5-9 s.",
    ["Exemple"] = "Beispiel",
    ["Exemple : 10 cases par ligne et 80 places en tout font 8 lignes."] = "Beispiel: 10 Felder pro Zeile und 80 Plätze insgesamt ergeben 8 Zeilen.",
    ["Exemple : 3 = jusqu'à trois icônes côte à côte (Fulgurance, Exécution et Vengeance prêtes ensemble). Avec 1, seule la première est montrée."] = "Beispiel: 3 = bis zu drei Symbole nebeneinander (Überwältigen, Hinrichten und Rache gleichzeitig bereit). Bei 1 wird nur das erste gezeigt.",
    ["Exemple : clic droit sur le portrait d'un paladin, « Demander un buff », « Bénédiction des rois » : il reçoit « Salut, rois stp ? Merci :) » (prêtre : « buff endu », mage : « buff int »…). La liste dépend de sa classe — paladin : les bénédictions ; prêtre : Robustesse, Esprit divin, Protection contre l'Ombre ; druide : Marque du fauve, Épines ; mage : Intelligence des arcanes, nourriture, eau ; démoniste : Respiration interminable, pierre de soins, invocation ; chaman : Respiration aquatique, Marche sur l'eau. En haut de la liste, « Tous ses buffs » envoie « Salut, buff stp ? Merci :) ». Marche aussi sur un nom cliqué dans le chat. En instance, si le jeu cache son nom, la demande part dans le chat du groupe."] = "Beispiel: Rechtsklick auf das Porträt eines Paladins, „Um einen Buff bitten“, „Segen der Könige“: Er erhält „Hi, could I get BoK pls? Thanks :)“ (Priester: „Fort“, Magier: „Int“ ...). Die Liste hängt von seiner Klasse ab – Paladin: die Segen; Priester: Seelenstärke, Göttlicher Wille, Schattenschutz; Druide: Mal der Wildnis, Dornen; Magier: Arkane Intelligenz, Essen, Wasser; Hexenmeister: Unendlicher Atem, Gesundheitsstein, Beschwörung; Schamane: Wasseratmung, Wasserwandeln. Oben in der Liste sendet „Alle seine Buffs“ „Hi, could I get buff pls? Thanks :)“. Funktioniert auch bei einem im Chat angeklickten Namen. In einer Instanz geht die Anfrage in den Gruppenchat, wenn das Spiel seinen Namen verbirgt.",
    ["Exemple : ton Pain de seigle et tes Potions de soins s'affichent ensemble sous Consommables, ton Étoffe de lin sous Artisanat, tes Bottes sous Équipement. Sous Poubelle : l'Os brisé gris et tout ce que la vente automatique vendra chez le marchand. Tes places vides sont à la fin, sous Libre. Seul l'affichage change : les objets ne bougent pas dans tes sacs (le bouton Trier range toujours les sacs du jeu). Coupé : tes sacs à la suite, case par case."] = "Beispiel: Dein Roggenbrot und deine Heiltränke erscheinen zusammen unter Verbrauchsgüter, dein Leinenstoff unter Handwerkswaren, deine Stiefel unter Ausrüstung. Unter Plunder: der graue Zerbrochene Knochen und alles, was der Autoverkauf beim Händler verkauft. Deine leeren Plätze sind am Ende, unter Frei. Nur die Anzeige ändert sich: Die Gegenstände bewegen sich nicht in deinen Taschen (die Schaltfläche Sortieren sortiert weiterhin die Spieltaschen). Aus: deine Taschen nacheinander, Feld für Feld.",
    ["Exemple : tu parles au garde, ses options et ses quêtes s'affichent en lignes cliquables ; tu choisis une quête, son texte, ses objectifs et ses récompenses s'affichent en grand avec les boutons Accepter / Refuser. Les récompenses sont des tuiles colorées selon leur rareté : survol pour l'infobulle, clic pour choisir, double-clic pour choisir et rendre la quête. Ta touche Platyplus et Échap marchent comme avant. Coupé : les fenêtres du jeu reviennent."] = "Beispiel: Du sprichst mit der Wache, ihre Optionen und Quests erscheinen als anklickbare Zeilen; du wählst eine Quest, und Text, Ziele und Belohnungen erscheinen groß mit den Schaltflächen Annehmen / Ablehnen. Die Belohnungen sind nach Seltenheit gefärbte Kacheln: Überfahren für den Tooltip, Klick zum Wählen, Doppelklick zum Wählen und Abgeben der Quest. Deine Platyplus-Taste und Esc funktionieren wie zuvor. Aus: Die Spielfenster kommen zurück.",
    ["Exemple : un mage dont un sort se met à briller sur sa barre voit son icône apparaître en grand avec la touche. Mage, démoniste, prêtre, druide et chaman passent surtout par là, comme les sorts de rune. Les sorts réactifs du guerrier peuvent aussi briller : coupe cette option si tu ne veux que la liste des sorts réactifs."] = "Beispiel: Beginnt bei einem Magier ein Zauber auf der Leiste zu leuchten, erscheint sein Symbol groß mit der Taste. Magier, Hexenmeister, Priester, Druide und Schamane nutzen vor allem das, genau wie Runenzauber. Auch die Reaktionsfähigkeiten des Kriegers können leuchten: Schalte diese Option aus, wenn du nur die Liste der Reaktionsfähigkeiten willst.",
    ["Exemple : un mage dont un sort se met à briller sur sa barre voit son icône apparaître en grand avec la touche. Mage, démoniste, prêtre, druide et chaman passent surtout par là, comme les sorts de rune. Pour un guerrier, Fulgurance et les autres brillent peut-être aussi (à confirmer en jeu) : coupe cette option si tu ne veux que la liste de sorts réactifs."] = "Beispiel: Bei einem Magier, dessen Zauber auf der Leiste aufleuchtet, erscheint das Symbol groß mit der Taste. Magier, Hexenmeister, Priester, Druide und Schamane laufen hauptsächlich darüber, ebenso Runenzauber. Beim Krieger leuchten Überwältigen und die anderen vielleicht auch (im Spiel zu bestätigen): Schalte diese Option aus, wenn du nur die Liste der reaktiven Zauber willst.",
    ["Exemple : un prêtre et un druide dans ton groupe, et tu n'as ni Robustesse ni Marque du fauve : deux icônes apparaissent au-dessus de ton personnage, avec « Ariane » et « Cléo » dessous. Proposés : Robustesse (prêtre), Marque du fauve (druide), Intelligence des arcanes (mage, si tu utilises de la mana), une bénédiction (paladin : puissance, ou sagesse si tu utilises de la mana ; n'importe laquelle compte). Cachée en combat."] = "Beispiel: Ein Priester und ein Druide sind in deiner Gruppe, und dir fehlen Seelenstärke und Mal der Wildnis: Zwei Symbole erscheinen über deiner Figur, mit „Ariane“ und „Cleo“ darunter. Angeboten werden: Seelenstärke (Priester), Mal der Wildnis (Druide), Arkane Intelligenz (Magier, wenn du Mana nutzt), ein Segen (Paladin: Macht, oder Weisheit, wenn du Mana nutzt; jeder zählt). Im Kampf verborgen.",
    ["Exemple : « Fulgurance » écrit sous l'icône. Coupé, l'alerte est plus compacte."] = "Beispiel: „Überwältigen“ steht unter dem Symbol. Aus: Die Warnung ist kompakter.",
    ["Exemple avec le seuil à 20 % : ton healer a 6 800 de mana au maximum ; dès qu'il passe sous 1 360, la barre et son contour deviennent rouges et la barre clignote une fois. L'alerte se retire quand il remonte à 25 %, pour ne pas clignoter autour du seuil. Pendant les combats où le jeu cache la mana des alliés, la barre devient seulement rouge (sans clignotement ni son)."] = "Beispiel mit der Schwelle bei 20 %: Dein Heiler hat höchstens 6.800 Mana; sobald es unter 1.360 fällt, werden Leiste und Kontur rot und die Leiste blinkt einmal. Die Warnung endet, wenn es wieder auf 25 % steigt, damit nichts um die Schwelle herum flackert. In Kämpfen, in denen das Spiel das Mana der Verbündeten verbirgt, wird die Leiste nur rot (ohne Blinken oder Ton).",
    ["Expérience"] = "Erfahrung",
    ["Expérience : le pourcentage du niveau. Clique dessus pour voir l'XP par heure, le temps avant le niveau ou les mobs restants."] = "Erfahrung: der Prozentsatz der Stufe. Klick darauf, um die EP pro Stunde, die Zeit bis zur nächsten Stufe oder die verbleibenden Gegner zu sehen.",
    ["F  ·  Accepter"] = "F  ·  Annehmen",
    ["F  ·  Continuer"] = "F  ·  Weiter",
    ["FPS"] = "FPS",
    ["Fabriqué"] = "Hergestellt",
    ["Facteur de recul"] = "Rückstoßfaktor",
    ["Faire la paix"] = "Frieden schließen",
    ["Fait apparaître quelques lignes d'exemple pour voir le résultat."] = "Zeigt ein paar Beispielzeilen, damit du das Ergebnis siehst.",
    ["Familier · %s"] = "Begleiter · %s",
    ["Fenêtre classique"] = "Klassisches Fenster",
    ["Fenêtre de chat Platyplus"] = "Platyplus-Chatfenster",
    ["Fenêtre de menace"] = "Bedrohungsfenster",
    ["Fenêtre de quête"] = "Questfenster",
    ["Fenêtre de quête et de dialogue"] = "Quest- und Dialogfenster",
    ["Fenêtre des jets de dés"] = "Würfelfenster",
    ["Fenêtre du personnage"] = "Charakterfenster",
    ["Fenêtre du personnage (touche C) : équipement, niveau d'objet, réputation, compétences, monnaies."] = "Charakterfenster (Taste C): Ausrüstung, Gegenstandsstufe, Ruf, Fertigkeiten, Währungen.",
    ["Fenêtres"] = "Fenster",
    ["Ferme la fenêtre (Échap marche aussi)."] = "Schließt das Fenster (Esc funktioniert auch).",
    ["Fermer"] = "Schließen",
    ["Fine (jeu)"] = "Dünn (Spiel)",
    ["Fluidité de l'affichage. Vert : 50 et plus, orange : 25 à 49, rouge : moins de 25."] = "Flüssigkeit der Anzeige. Grün: 50 und mehr, orange: 25 bis 49, rot: weniger als 25.",
    ["Fluidité du jeu (images par seconde)."] = "Spielflüssigkeit (Bilder pro Sekunde).",
    ["Flux Platyplus - glisse-moi"] = "Platyplus-Feed - zieh mich",
    ["Flux de butin"] = "Beute-Feed",
    ["Flux de butin à l'écran"] = "Beutefluss auf dem Bildschirm",
    ["Flux à l'écran"] = "Feed auf dem Bildschirm",
    ["Flèches haut / bas : ce que tu as tapé"] = "Pfeiltasten hoch / runter: das, was du getippt hast",
    ["Focalisation"] = "Fokus",
    ["Folie"] = "Wahnsinn",
    ["Fond uni sans les bords arrondis (sa couleur et sa transparence restent celles réglées dans le jeu), onglets plats avec un trait bleu sous celui qui est actif, zone de saisie sombre bordée de bleu. Coupé : le chat redevient exactement comme avant."] = "Einfarbiger Hintergrund ohne abgerundete Ränder (Farbe und Transparenz bleiben wie im Spiel eingestellt), flache Reiter mit blauem Strich unter dem aktiven, dunkles Eingabefeld mit blauem Rand. Aus: Der Chat ist wieder genau wie vorher.",
    ["Fond uni, onglets plats, zone de saisie sombre."] = "Einfarbiger Hintergrund, flache Reiter, dunkles Eingabefeld.",
    ["Fond, bord et coins arrondis comme réglés dans la carte « Cadre »."] = "Hintergrund, Rand und abgerundete Ecken wie in der Karte „Rahmen“ eingestellt.",
    ["Format"] = "Format",
    ["Fragments d'âme"] = "Seelensplitter",
    ["Fulgurance, Vengeance, Exécution, Ivresse de la victoire"] = "Überwältigen, Rache, Hinrichten, Siegesrausch",
    ["Fureur"] = "Wut",
    ["Gagné par %s"] = "Gewonnen von %s",
    ["Gagnée cette session"] = "In dieser Sitzung gewonnen",
    ["Garde l'étincelle de butin du jeu allumée."] = "Hält den Beutefunken des Spiels eingeschaltet.",
    ["Garder les apparences que je n'ai pas"] = "Erscheinungen behalten, die ich nicht habe",
    ["Garder les derniers messages"] = "Letzte Nachrichten behalten",
    ["Gardé pour ce personnage"] = "Für diesen Charakter gespeichert",
    ["Glisse ici un objet de tes sacs"] = "Leg hier einen Gegenstand aus deinen Taschen ab",
    ["Glisse ici un sort de ton grimoire"] = "Leg hier einen Zauber aus deinem Zauberbuch ab",
    ["Gris"] = "Grau",
    ["Gris : %d"] = "Grau: %d",
    ["Groupe"] = "Gruppe",
    ["Groupe (%d)"] = "Gruppe (%d)",
    ["Groupes, duels et invocations"] = "Gruppen, Duelle und Beschwörungen",
    ["Groupes, duels et invocations acceptés ou refusés pour toi ; une interface plus calme."] = "Gruppen, Duelle und Beschwörungen werden für dich angenommen oder abgelehnt; eine ruhigere Oberfläche.",
    ["Guerrier"] = "Krieger",
    ["Guerrier : Fulgurance, Vengeance, Exécution, Ivresse de la victoire. Voleur : Riposte. Chasseur : Contre-attaque, Morsure de la mangouste, Ordre de tuer. Paladin : Marteau de courroux. Exemple : tu pares un coup, Riposte apparaît avec sa touche. Coupé, ces sorts ne sont plus annoncés (sauf s'ils brillent et que « Sorts qui brillent » est actif)."] = "Krieger: Überwältigen, Rache, Hinrichten, Siegesrausch. Schurke: Riposte. Jäger: Gegenangriff, Mungobiss, Tötungsbefehl. Paladin: Hammer des Zorns. Beispiel: Du parierst einen Schlag, Riposte erscheint mit ihrer Taste. Aus: Diese Zauber werden nicht mehr angezeigt (außer sie leuchten und „Leuchtende Zauber“ ist aktiv).",
    ["Guerrier : une petite icône quand le buff est actif."] = "Krieger: ein kleines Symbol, solange der Buff aktiv ist.",
    ["Guilde"] = "Gilde",
    ["HDV"] = "AH",
    ["HDV : %s ne sera plus proposé (/pp hdv exclus pour la liste)"] = "AH: %s wird nicht mehr vorgeschlagen (/pp hdv exclus für die Liste)",
    ["HDV : %s refusé"] = "AH: %s abgelehnt",
    ["HDV : %s refusé (%s)"] = "AH: %s abgelehnt (%s)",
    ["HDV : coche d'abord les objets à mettre en vente (clic sur la ligne)"] = "AH: hake zuerst die einzustellenden Gegenstände an (Klick auf die Zeile)",
    ["HDV : le jeu demande une confirmation pour %s. Clique encore (ou ta touche) pour confirmer."] = "AH: das Spiel verlangt eine Bestätigung für %s. Klicke noch einmal (oder deine Taste) zum Bestätigen.",
    ["HDV : le scan complet n'a rien renvoyé."] = "AH: der Komplettscan hat nichts zurückgegeben.",
    ["HDV : le serveur n'autorise un scan complet que toutes les 15 min, réessaie dans %d min."] = "AH: der Server erlaubt einen Komplettscan nur alle 15 Min., versuche es in %d Min. erneut.",
    ["HDV : pas de réponse au scan complet, réessaie plus tard."] = "AH: keine Antwort auf den Komplettscan, versuche es später erneut.",
    ["HDV : prix trouvés."] = "AH: Preise gefunden.",
    ["HDV : recherche des prix en cours, patiente un instant"] = "AH: Preissuche läuft, einen Moment Geduld",
    ["HDV : rien de prêt à mettre en vente"] = "AH: nichts zum Einstellen bereit",
    ["HDV : scan complet lancé (tous les prix de l'HDV, quelques secondes)..."] = "AH: Komplettscan gestartet (alle Preise des Auktionshauses, einige Sekunden)...",
    ["HDV : scan complet refusé par le jeu"] = "AH: Komplettscan vom Spiel abgelehnt",
    ["HDV : scan complet terminé, %d objet(s) avec un prix."] = "AH: Komplettscan beendet, %d Gegenstand/Gegenstände mit Preis.",
    ["Hauteur de la barre"] = "Höhe der Leiste",
    ["Healer suivi"] = "Verfolgter Heiler",
    ["Histoire de la quête"] = "Geschichte der Quest",
    ["Hors combat"] = "Außerhalb des Kampfes",
    ["Hors combat : boit la boisson la plus haute (eau, jus...) pour la mana. En combat : boit ta meilleure potion de mana. Remettre « aucune » coupe la touche."] = "Außerhalb des Kampfes: trinkt das beste Getränk (Wasser, Saft ...) für Mana. Im Kampf: trinkt deinen besten Manatrank. Wieder auf „keiner“ gestellt, schaltet die Taste ab.",
    ["Hors combat : l'icône du buff manquant avec le nom de l'allié."] = "Außerhalb des Kampfes: das Symbol des fehlenden Buffs mit dem Namen des Verbündeten.",
    ["Hors combat : l'icône du buff qui te manque et le nom de l'allié qui peut te le donner."] = "Außerhalb des Kampfes: das Symbol des fehlenden Buffs und der Name des Verbündeten, der ihn dir geben kann.",
    ["Hors combat : mange la nourriture la plus haute que tu peux utiliser. En combat : boit ta meilleure potion de soins. « La plus haute » = niveau requis, puis niveau de l'objet. Remettre « aucune » coupe la touche."] = "Außerhalb des Kampfes: isst die beste Nahrung, die du nutzen kannst. Im Kampf: trinkt deinen besten Heiltrank. „Beste“ = benötigte Stufe, dann Gegenstandsstufe. Wieder auf „keiner“ gestellt, schaltet die Taste ab.",
    ["Hors combat · quête · rare"] = "Außer Kampf · Quest · selten",
    ["Hostile"] = "Feindlich",
    ["Hôtel des ventes"] = "Auktionshaus",
    ["ID d'objet ou lien, puis Entrée"] = "Gegenstands-ID oder Link, dann Eingabe",
    ["Icône & infos"] = "Symbol & Infos",
    ["Icône Platyplus"] = "Platyplus-Symbol",
    ["Icône de Maîtrise du blocage"] = "Schildblock-Symbol",
    ["Icônes"] = "Symbole",
    ["Il ne t'attaque que si tu le tapes."] = "Greift dich nur an, wenn du ihn angreifst.",
    ["Il tape un allié"] = "Er schlägt einen Verbündeten",
    ["Il te manque encore des objets ou des objectifs."] = "Dir fehlen noch Gegenstände oder Aufgaben.",
    ["Il te tape"] = "Er schlägt dich",
    ["Images par seconde"] = "Bilder pro Sekunde",
    ["Immersif"] = "Immersiv",
    ["Immobilise"] = "Hält fest",
    ["Incantations"] = "Zauberwirken",
    ["Inclure les objets « lié quand équipé »"] = "„Beim Anlegen gebunden“-Gegenstände einbeziehen",
    ["Inhabituel"] = "Ungewöhnlich",
    ["Interaction rapide"] = "Schnellinteraktion",
    ["Interagit avec ce que tu survoles, sinon avec la cible la plus proche."] = "Interagiert mit dem, was du überfährst, sonst mit dem nächsten Ziel.",
    ["Interface"] = "Oberfläche",
    ["Interface et caméra"] = "Oberfläche und Kamera",
    ["Interruptible"] = "Unterbrechbar",
    ["Inutilisable"] = "Unbenutzbar",
    ["Jamais moins que le marchand"] = "Nie weniger als der Händler",
    ["Je joue"] = "Ich spiele",
    ["Jets /roll"] = "/roll-Würfe",
    ["Jets de butin"] = "Beutewürfe",
    ["Jets de dés en groupe"] = "Würfe in der Gruppe",
    ["Jets en cours"] = "Laufende Würfe",
    ["Jeu"] = "Spiel",
    ["Joue un avertissement quand l'alerte se déclenche. Hors combat, pas de son : un healer qui boit est à sec exprès. Le bouton « Aperçu » le fait entendre."] = "Spielt eine Warnung ab, wenn die Warnung ausgelöst wird. Außerhalb des Kampfes kein Ton: Ein trinkender Heiler hat absichtlich kein Mana. Die Schaltfläche „Vorschau“ lässt ihn dich hören.",
    ["Jouer"] = "Abspielen",
    ["Journal des donjons"] = "Dungeonjournal",
    ["L'HDV garde 5 % de chaque vente. Exemple : minerai à 18 pc à l'HDV, il te reste 17 pc, contre 5 pc chez le marchand : il est mis en vente. À 5 pc à l'HDV, il ne te resterait que 4 pc : il est marqué « marchand mieux » et reste dans tes sacs."] = "Das Auktionshaus behält 5 % jedes Verkaufs. Beispiel: Erz zu 18 K im Auktionshaus lässt dir 17 K, gegenüber 5 K beim Händler: Es wird eingestellt. Bei 5 K im Auktionshaus bekämst du nur 4 K: Es wird als „Händler besser“ markiert und bleibt in deinen Taschen.",
    ["L'addon DungeonJournal séparé est activé : c'est lui qui tourne, avec la liste des donjons, « À ton niveau » et le style de Platyplus posés dessus. Le journal intégré à Platyplus reste éteint et garde une copie de ses réglages, de tes favoris et de ta progression : désactive DungeonJournal dans la liste des addons (écran de choix du personnage) puis relance le jeu pour revenir au journal intégré."] = "Das separate Addon DungeonJournal ist aktiviert: Es läuft, mit der Dungeonliste, „Auf deiner Stufe“ und dem Stil von Platyplus darübergelegt. Das in Platyplus enthaltene Journal bleibt aus und behält eine Kopie seiner Einstellungen, deiner Favoriten und deines Fortschritts: Deaktiviere DungeonJournal in der Addon-Liste (Charakterauswahl) und starte das Spiel neu, um zum enthaltenen Journal zurückzukehren.",
    ["L'alerte apparaît quand le sort est vraiment utilisable (bonne posture, assez de rage, pas en recharge) et disparaît dès qu'il ne l'est plus. La touche est celle du bouton où tu as rangé le sort : un sort absent de tes barres n'est pas annoncé. Choisis les sorts surveillés dans la carte du dessous. /pp proc liste tes sorts surveillés et leur touche."] = "Die Warnung erscheint, wenn der Zauber wirklich einsetzbar ist (richtige Haltung, genug Wut, keine Abklingzeit), und verschwindet, sobald er es nicht mehr ist. Die Taste ist die der Schaltfläche, auf die du den Zauber gelegt hast: Ein Zauber, der nicht auf deinen Leisten liegt, wird nicht angezeigt. Wähle die überwachten Zauber in der Karte darunter. /pp proc listet deine überwachten Zauber und ihre Taste auf.",
    ["L'alerte quand une technique devient utilisable (Fulgurance, Riposte…) : quoi surveiller, comment l'afficher."] = "Die Warnung, wenn eine Fähigkeit nutzbar wird (Überwältigen, Riposte …): was beobachtet wird und wie sie angezeigt wird.",
    ["L'alerte se déclenche quand il te reste ce nombre d'emplacements libres, ou moins."] = "Die Warnung wird ausgelöst, wenn du noch so viele freie Plätze hast oder weniger.",
    ["L'argent de ce personnage."] = "Das Geld dieses Charakters.",
    ["L'aspect de la barre colorée. Unie = couleur plate, sans reflet."] = "Das Aussehen der farbigen Leiste. Einfarbig = flache Farbe, ohne Glanz.",
    ["L'heure devant chaque message"] = "Die Uhrzeit vor jeder Nachricht",
    ["L'icône Platyplus"] = "Das Platyplus-Symbol",
    ["L'icône Platyplus et sa barre d'infos, où tu veux à l'écran."] = "Das Platyplus-Symbol und seine Infoleiste, wo du willst auf dem Bildschirm.",
    ["L'icône du sort qui vient de devenir utilisable, sous ton personnage, avec la touche à presser."] = "Das Symbol des Zaubers, der gerade nutzbar wurde, unter deinem Charakter, mit der Taste, die du drücken musst.",
    ["L'étincelle du jeu oublie certains cadavres, les boss notamment. Une fois le combat fini, un cadavre qui a encore du butin pour toi brille quand tu t'en approches. Elle dit seulement « il reste du butin », pas quoi. Le jeu pose alors sa plaque de nom (nom et barre de vie) sur ce cadavre : c'est elle qui porte l'étincelle. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Der Funke des Spiels vergisst manche Leichen, vor allem Bosse. Nach dem Kampf glänzt eine Leiche, die noch Beute für dich hat, wenn du dich näherst. Er sagt nur „es gibt noch Beute“, nicht was. Das Spiel setzt dann seine Namensplakette (Name und Lebensleiste) auf diese Leiche: Sie trägt den Funken. Nutzt das Interaktionsziel des Spiels: das nächste Objekt, bis etwa 15 m, rund um dich. Dafür schaltet Platyplus „Interaktionstaste aktivieren“ und die Interaktionssymbole der Weltobjekte des Spiels ein und stellt sie wie zuvor wieder her, wenn du alle Funken unten ausschaltest. Kein Funke während eines Kampfes.",
    ["La barre de sort sous la plate d'un mob qui incante."] = "Die Zauberleiste unter der Namensplakette eines Gegners, der wirkt.",
    ["La fenêtre de réglages du journal lui-même : bouton de la minicarte, infobulles des objets, quêtes de classe et de métier, mode RPG... (aussi : /dj options)."] = "Das Einstellungsfenster des Journals selbst: Minikarten-Schaltfläche, Gegenstands-Tooltips, Klassen- und Berufsquests, RPG-Modus ... (auch: /dj options).",
    ["La langue du message envoyé (le menu reste en français). En anglais, avec les abréviations des joueurs : « Hi, could I get BoK pls? Thanks :) » (Fort, MotW, Int…) ; « Tous ses buffs » : « Hi, could I get buff pls? Thanks :) »."] = "Die Sprache der gesendeten Nachricht (das Menü bleibt auf Französisch). Auf Englisch, mit den Abkürzungen der Spieler: „Hi, could I get BoK pls? Thanks :)“ (Fort, MotW, Int ...); „Alle seine Buffs“: „Hi, could I get buff pls? Thanks :)“.",
    ["La menace d'un coup d'œil"] = "Bedrohung auf einen Blick",
    ["La repérer au milieu d'un pack."] = "Ihn mitten in einem Gegnerrudel erkennen.",
    ["La touche"] = "Die Taste",
    ["La touche choisie interagit d'abord avec ce que la souris survole, sinon avec la cible d'interaction la plus proche : PNJ, coffre, plante, cadavre à dépouiller. Coupée, Platyplus ne lie plus aucune touche."] = "Die gewählte Taste interagiert zuerst mit dem, was die Maus überfährt, sonst mit dem nächsten Interaktionsziel: NPC, Truhe, Pflanze, Leiche zum Häuten. Ausgeschaltet bindet Platyplus keine Taste mehr.",
    ["La touche à presser, en gros sous l'icône (« 3 », « Maj+E »)."] = "Die zu drückende Taste, groß unter dem Symbol („3“, „Umschalt+E“).",
    ["Laisser le jeu choisir"] = "Das Spiel wählen lassen",
    ["Lancer les sorts à l'appui de la touche"] = "Zauber beim Tastendruck wirken",
    ["Langue"] = "Sprache",
    ["Langue changée. Les textes déjà affichés ailleurs (barre d'infos, options du jeu) suivront au prochain /reload."] = "Sprache geändert. Bereits angezeigte Texte an anderer Stelle (Infoleiste, Spieloptionen) folgen beim nächsten /reload.",
    ["Langue de Platyplus"] = "Platyplus-Sprache",
    ["Langue de la demande"] = "Sprache der Anfrage",
    ["Langue des textes de Platyplus. Les textes pas encore traduits restent en anglais, ou en français à défaut."] = "Sprache der Platyplus-Texte. Noch nicht übersetzte Texte bleiben auf Englisch, ersatzweise auf Französisch.",
    ["Largeur"] = "Breite",
    ["Largeur de la barre de coups blancs."] = "Breite der Leiste für normale Angriffe.",
    ["Largeur de la barre, en points d'interface."] = "Breite der Leiste in Oberflächenpunkten.",
    ["Latence"] = "Latenz",
    ["Le bord de la plate de ta cible est plus épais et de la couleur choisie."] = "Der Rand der Namensplakette deines Ziels ist dicker und hat die gewählte Farbe.",
    ["Le butin sans clics"] = "Beute ohne Klicks",
    ["Le choix est gardé tout de suite, mais les fenêtres déjà construites gardent l'ancienne langue : recharge l'interface (bouton ci-dessous ou /reload)."] = "Die Wahl wird sofort gespeichert, aber bereits erstellte Fenster behalten die alte Sprache: Lade die Oberfläche neu (Schaltfläche unten oder /reload).",
    ["Le clignotement fait toujours trois éclats, plus ou moins vite."] = "Das Blinken besteht immer aus drei Impulsen, mehr oder weniger schnell.",
    ["Le confort tout-en-un"] = "Der Komfort in einem",
    ["Le confort tout-en-un pour WoW Forever · v%s"] = "Der Komfort in einem für WoW Forever · v%s",
    ["Le confort tout-en-un · v%s"] = "Der Komfort in einem · v%s",
    ["Le contour et le fond autour de la barre."] = "Die Kontur und der Hintergrund um die Leiste.",
    ["Le fond visible là où le mob a perdu de la vie. 0 % = transparent."] = "Der Hintergrund, der sichtbar ist, wo der Gegner Leben verloren hat. 0 % = transparent.",
    ["Le gros cadre sombre du jeu remplacé par le nôtre, réglable ci-dessous."] = "Der große dunkle Rahmen des Spiels, durch unseren ersetzt, unten einstellbar.",
    ["Le healer est celui que le groupe désigne comme soigneur (file de donjon, ou rôle donné par le chef de groupe). Si personne n'a ce rôle, cible ton healer et clique « Mon healer = ma cible ». S'il y a plusieurs soigneurs, la barre suit le premier de la liste du groupe : choisis le tien avec le bouton."] = "Der Heiler ist, wen die Gruppe als Heiler bestimmt (Dungeonsuche oder vom Gruppenleiter vergebene Rolle). Hat niemand diese Rolle, wähle deinen Heiler als Ziel und klicke „Mein Heiler = mein Ziel“. Gibt es mehrere Heiler, folgt die Leiste dem ersten in der Gruppenliste: Wähle deinen mit der Schaltfläche.",
    ["Le jeu fait briller les objets de quête à ramasser (une caisse, une torche par terre...), mais un préréglage graphique coupe cette étincelle. Platyplus la remet à la connexion et juste après chaque changement graphique. Ton mode de contour (outline) n'est pas touché. Couper cette option ne prend effet qu'après un redémarrage du jeu : /reload ne suffit pas."] = "Das Spiel lässt aufzusammelnde Questgegenstände glänzen (eine Kiste, eine Fackel am Boden ...), aber eine Grafikvorgabe schaltet diesen Funken aus. Platyplus schaltet ihn beim Anmelden und direkt nach jeder Grafikänderung wieder ein. Dein Konturmodus (Outline) wird nicht berührt. Das Ausschalten dieser Option wirkt erst nach einem Spielneustart: /reload genügt nicht.",
    ["Le jeu marque déjà la plupart des objets de quête avec son étincelle de butin. Ceci en ajoute une autre sur ceux que ton journal demande encore, d'après le nom de l'objectif (« Caisse de provisions »...). Coupé par défaut. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Das Spiel markiert die meisten Questgegenstände schon mit seinem Beutefunken. Dies fügt einen weiteren auf denen hinzu, die dein Journal noch verlangt, anhand des Zielnamens („Vorratskiste“ ...). Standardmäßig aus. Nutzt das Interaktionsziel des Spiels: das nächste Objekt, bis etwa 15 m, rund um dich. Dafür schaltet Platyplus „Interaktionstaste aktivieren“ und die Interaktionssymbole der Weltobjekte des Spiels ein und stellt sie wie zuvor wieder her, wenn du alle Funken unten ausschaltest. Kein Funke während eines Kampfes.",
    ["Le jeu protège une partie des caractéristiques en ce moment : affichage simplifié, sans détail au survol. Tout revient dès qu'il les rend lisibles."] = "Das Spiel schützt im Moment einen Teil der Werte: vereinfachte Anzeige, ohne Detail beim Überfahren. Alles kommt zurück, sobald es sie wieder lesbar macht.",
    ["Le joueur dont la barre montre la mana. « Aucun » : ton groupe n'a pas de soigneur désigné et tu n'as pas choisi ton healer à la main."] = "Der Spieler, dessen Mana die Leiste zeigt. „Keiner“: Deine Gruppe hat keinen bestimmten Heiler und du hast deinen Heiler nicht von Hand gewählt.",
    ["Le journal aux couleurs de Platyplus : fond sombre arrondi, liserés fins, sélection en bleu, texte clair, et plus de parchemin sous les quêtes. Rien ne bouge : mêmes pages, mêmes boutons. Éteint : le look d'origine du journal (pierre, bronze et or). Prend effet après /reload."] = "Das Journal in Platyplus-Farben: abgerundeter dunkler Hintergrund, feine Linien, blaue Auswahl, heller Text und kein Pergament mehr unter den Quests. Nichts verschiebt sich: gleiche Seiten, gleiche Schaltflächen. Aus: das ursprüngliche Aussehen des Journals (Stein, Bronze und Gold). Wirkt nach /reload.",
    ["Le journal de quêtes de la carte du monde du jeu."] = "Das Questlog der Weltkarte des Spiels.",
    ["Le journal des donjons : boss, butin, quêtes et plans de chaque donjon."] = "Das Dungeonjournal: Bosse, Beute, Quests und Karten jedes Dungeons.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part : Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons."] = "Das Dungeon-Journal stammt aus Exehns Addon DungeonJournal, das separat installiert ist: Platyplus öffnet es von hier, über das Symbolmenü und mit /pp donjons.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part. Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons, et pose dessus sa liste des donjons, « À ton niveau » et son style, sans rien changer dans l'addon."] = "Das Dungeonjournal stammt aus Exehns Addon DungeonJournal, das separat installiert ist. Platyplus öffnet es von hier, über das Symbolmenü und mit /pp donjons, und legt seine Dungeonliste, „Auf deiner Stufe“ und seinen Stil darüber, ohne etwas am Addon zu ändern.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons, et posera dessus sa liste des donjons, « À ton niveau » et son style."] = "Das Dungeonjournal ist in dieser Version von Platyplus nicht enthalten. Installiere Exehns Addon DungeonJournal von CurseForge: Platyplus öffnet es dann von diesem Reiter, über das Symbolmenü und mit /pp donjons, und legt seine Dungeonliste, „Auf deiner Stufe“ und seinen Stil darüber.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons."] = "Das Dungeon-Journal ist in dieser Version von Platyplus nicht enthalten. Installiere Exehns Addon DungeonJournal von CurseForge: Platyplus öffnet es dann über diesen Reiter, das Symbolmenü und /pp donjons.",
    ["Le marchand t'en donne"] = "Der Händler gibt dir dafür",
    ["Le minuteur de ton attaque automatique : la barre se remplit jusqu'au prochain coup blanc. Pratique pour placer Frappe héroïque ou Heurtoir au bon moment."] = "Der Timer deines Automatikangriffs: Die Leiste füllt sich bis zum nächsten normalen Angriff. Praktisch, um Heldenhafter Stoß oder Zerschmettern zum richtigen Zeitpunkt einzusetzen.",
    ["Le mode Recommandé, plus : les groupes de tes amis et de ta guilde acceptés, les invocations et les résurrections acceptées, les duels refusés, tout le courrier ouvert d'un coup, les quêtes acceptées et rendues sans appuyer sur la touche, la barre de mana du healer, la caméra plus loin, les têtes parlantes masquées, les objets de quête qui brillent."] = "Der Modus Empfohlen, dazu: Gruppeneinladungen von Freunden und Gilde angenommen, Beschwörungen und Wiederbelebungen angenommen, Duelle abgelehnt, die ganze Post auf einmal geöffnet, Quests ohne Tastendruck angenommen und abgegeben, die Manaleiste des Heilers, die weiter entfernte Kamera, sprechende Köpfe ausgeblendet, leuchtende Questgegenstände.",
    ["Le nom du sort, en petit sous la touche."] = "Der Zaubername, klein unter der Taste.",
    ["Le petit logo en haut à droite de la fenêtre de chat."] = "Das kleine Logo oben rechts im Chatfenster.",
    ["Le prix de tes objets à l'hôtel des ventes, partout : dans les infobulles et avant de fabriquer. Les prix viennent d'un scan complet de l'HDV et de ce que l'assistant trouve."] = "Der Preis deiner Gegenstände im Auktionshaus, überall: in Tooltips und vor dem Herstellen. Die Preise stammen aus einem vollständigen Auktionshaus-Scan und aus dem, was der Assistent findet.",
    ["Le son d'avertissement de raid, au plus une fois par seconde."] = "Der Warnton des Schlachtzugs, höchstens einmal pro Sekunde.",
    ["Le sort part quand tu appuies, pas quand tu relâches. Disponible seulement si le client connaît ce réglage."] = "Der Zauber wird beim Drücken ausgelöst, nicht beim Loslassen. Nur verfügbar, wenn der Client diese Einstellung kennt.",
    ["Les 100 dernières lignes de chaque fenêtre, pour la session suivante."] = "Die letzten 100 Zeilen jedes Fensters, für die nächste Sitzung.",
    ["Les adresses web écrites dans le chat (https://..., www....) deviennent des liens bleus. Un clic ouvre une petite fenêtre avec le lien déjà sélectionné : Ctrl+C pour le copier. Les messages protégés par le jeu (instances, combats de boss) ne sont jamais touchés."] = "Im Chat geschriebene Webadressen (https://..., www....) werden zu blauen Links. Ein Klick öffnet ein kleines Fenster mit dem bereits markierten Link: Strg+C zum Kopieren. Vom Spiel geschützte Nachrichten (Instanzen, Bosskämpfe) werden nie angetastet.",
    ["Les armes et armures de qualité inférieure ne sont pas proposées. Par défaut Inhabituel (vert) : l'équipement blanc ou gris ne se vend pas à l'HDV, il part chez le marchand. Les marchandises (minerais, herbes, tissus...) sont toujours proposées."] = "Waffen und Rüstungen niedrigerer Qualität werden nicht angeboten. Standardmäßig Ungewöhnlich (grün): Weiße oder graue Ausrüstung lässt sich im Auktionshaus nicht verkaufen, sie geht an den Händler. Waren (Erze, Kräuter, Stoffe ...) werden immer angeboten.",
    ["Les barres de vie au-dessus des mobs : couleurs de menace, quêtes, rares, et tout leur look."] = "Die Lebensleisten über den Gegnern: Bedrohungsfarben, Quests, Seltene und ihr gesamtes Aussehen.",
    ["Les barres de vie des mobs changent de couleur selon qui ils attaquent. Ton rôle (tank ou dégâts) est deviné tout seul."] = "Die Lebensleisten der Gegner ändern ihre Farbe, je nachdem, wen sie angreifen. Deine Rolle (Tank oder Schaden) wird automatisch erkannt.",
    ["Les dés lancés à la main dans le chat, rangés par objet annoncé."] = "Die im Chat von Hand geworfenen Würfel, nach angekündigtem Gegenstand sortiert.",
    ["Les dés lancés à la main, rangés du plus haut au plus bas, avec l'objet lié juste avant dans le chat."] = "Die von Hand geworfenen Würfel, vom höchsten zum niedrigsten sortiert, mit dem kurz zuvor im Chat verlinkten Gegenstand.",
    ["Les fenêtres de chat du jeu (quand la fenêtre Platyplus est coupée) et la zone de saisie, aux couleurs de Platyplus."] = "Die Chatfenster des Spiels (wenn das Platyplus-Fenster aus ist) und das Eingabefeld, in Platyplus-Farben.",
    ["Les fenêtres du jeu redessinées : plus grandes et plus lisibles."] = "Die Spielfenster neu gestaltet: größer und besser lesbar.",
    ["Les fonctions utiles sont allumées : la touche d'interaction, le loot instantané, la vente et la réparation, les alertes de combat, les plates de menace, les fenêtres Platyplus, le chat amélioré. Ce qui décide à ta place reste coupé : invitations, invocations, duels, courrier."] = "Die nützlichen Funktionen sind an: die Interaktionstaste, Sofortbeute, Verkauf und Reparatur, Kampfwarnungen, Bedrohungsplaketten, die Platyplus-Fenster, der verbesserte Chat. Was für dich entscheidet, bleibt aus: Einladungen, Beschwörungen, Duelle, Post.",
    ["Les fonctions utiles sont déjà allumées : tu peux fermer cette fenêtre et jouer tout de suite."] = "Die nützlichen Funktionen sind schon eingeschaltet: Du kannst dieses Fenster schließen und sofort losspielen.",
    ["Les fonctions utiles, sans rien décider à ta place. Le réglage de départ."] = "Die nützlichen Funktionen, ohne etwas für dich zu entscheiden. Die Starteinstellung.",
    ["Les messages arrivent comme d'habitude (tes réglages de canaux du jeu restent valables) et s'affichent dans la fenêtre Platyplus, une bulle par message, le nom dans la couleur de sa classe, le texte en clair. L'onglet Chat montre ce que les joueurs disent, l'onglet Jeu le reste (butin, expérience, système). Tire le bandeau pour la déplacer, le coin en bas à droite pour la redimensionner. Clic sur l'heure d'un message : le copier. La zone de saisie reste celle du jeu (Entrée pour écrire). Coupé : les fenêtres de chat du jeu reviennent."] = "Die Nachrichten kommen wie gewohnt an (deine Kanaleinstellungen des Spiels gelten weiter) und erscheinen im Platyplus-Fenster, eine Blase pro Nachricht, der Name in seiner Klassenfarbe, der Text schlicht. Der Reiter Chat zeigt, was die Spieler sagen, der Reiter Spiel den Rest (Beute, Erfahrung, System). Zieh den Titelbalken zum Verschieben, die untere rechte Ecke zum Ändern der Größe. Klick auf die Uhrzeit einer Nachricht: kopieren. Das Eingabefeld bleibt das des Spiels (Eingabe zum Schreiben). Aus: Die Chatfenster des Spiels kommen zurück.",
    ["Les miennes"] = "Meine",
    ["Les miennes : hostile, neutre, amical et « tapé par d'autres » aux couleurs ci-dessous, avec ta texture. Celles du jeu : la barre normale du jeu. Les joueurs gardent toujours les couleurs du jeu."] = "Meine: feindlich, neutral, freundlich und „von anderen getappt“ in den Farben unten, mit deiner Textur. Die des Spiels: die normale Leiste des Spiels. Spieler behalten immer die Farben des Spiels.",
    ["Les mobs qui ne se battent pas avec toi."] = "Gegner, die nicht mit dir kämpfen.",
    ["Les objets au choix s'affichent au milieu de l'écran, colorés selon leur rareté."] = "Die zur Auswahl stehenden Gegenstände erscheinen in der Bildschirmmitte, nach Seltenheit gefärbt.",
    ["Les objets exclus d'un clic droit dans le panneau de l'HDV seront de nouveau proposés."] = "Gegenstände, die per Rechtsklick im Auktionshaus-Panel ausgeschlossen wurden, werden wieder angeboten.",
    ["Les objets gris et l'équipement moins bon que le tien se vendent tout seuls. Tu peux les racheter chez le marchand."] = "Graue Gegenstände und Ausrüstung, die schlechter ist als deine, werden von selbst verkauft. Du kannst sie beim Händler zurückkaufen.",
    ["Les objets tirés au sort par le jeu (Besoin, Cupidité, Passer), boss par boss."] = "Die vom Spiel verlosten Gegenstände (Bedarf, Gier, Passen), Boss für Boss.",
    ["Les pièces nettement moins bonnes que ce que tu portes."] = "Teile, die deutlich schlechter sind als das, was du trägst.",
    ["Les plantes et les cadavres qui ont encore du butin pour toi scintillent quand tu approches."] = "Pflanzen und Leichen, die noch Beute für dich haben, funkeln, wenn du dich näherst.",
    ["Les plus dangereux d'abord"] = "Die gefährlichsten zuerst",
    ["Les sorts réactifs que Platyplus connaît pour ta classe. Pour en ajouter un autre, utilise la liste « Sorts ajoutés » juste en dessous."] = "Die reaktiven Zauber, die Platyplus für deine Klasse kennt. Um einen weiteren hinzuzufügen, nutze die Liste „Hinzugefügte Zauber“ direkt darunter.",
    ["Les tranches de niveau sont colorées selon ton niveau :\n|cff66e680vert|r à ton niveau, |cffffd133or|r bientôt (1 à 3 niveaux), |cffff6666rouge|r trop dur pour l'instant, |cff99a1b3gris|r dépassé.\nÀ droite : tes quêtes faites dans le donjon (✓ : toutes)."] = "Die Stufenabschnitte sind nach deiner Stufe gefärbt:\n|cff66e680grün|r auf deiner Stufe, |cffffd133gold|r bald (1 bis 3 Stufen), |cffff6666rot|r im Moment zu schwer, |cff99a1b3grau|r überholt.\nRechts: deine im Dungeon erledigten Quests (✓: alle).",
    ["Les étincelles (onglet Butin) règlent cette portée : coupe-les pour la changer ici."] = "Die Funken (Reiter Beute) legen diese Reichweite fest: Schalte sie aus, um sie hier zu ändern.",
    ["Lien [FR] pour traduire"] = "[FR]-Link zum Übersetzen",
    ["Lien web"] = "Weblink",
    ["Liens web cliquables"] = "Anklickbare Weblinks",
    ["Lignes au maximum"] = "Maximale Zeilen",
    ["Limite le nombre de pièces d'équipement vendues à chaque visite. Le rachat de Blizzard ne garde que les 12 derniers objets vendus : au-delà de 12, tu ne pourrais plus tout racheter en cas d'erreur."] = "Begrenzt die Zahl der bei jedem Besuch verkauften Ausrüstungsteile. Der Rückkauf von Blizzard behält nur die letzten 12 verkauften Gegenstände: Über 12 könntest du bei einem Irrtum nicht mehr alles zurückkaufen.",
    ["Lisibilité"] = "Lesbarkeit",
    ["Liste des donjons à gauche"] = "Dungeonliste links",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Listet die Gegner im Kampf auf (Plaketten, Bosse, Ziele deiner Gruppe). Die Farben sind die der Namensplaketten (Reiter Plaketten). In Dungeons verbirgt das Spiel manche Werte vor Addons: Die Farbe stimmt weiter, aber die Sortierung nach Leben und manche Zahlen können fehlen. Kein Klick zum Anvisieren: Das Spiel verbietet es im Kampf.",
    ["Liste les objets de tes sacs que l'HDV accepte, avec un prix pour chacun. Ne sont jamais proposés : objets liés, équipement blanc ou gris, outils de métier (pioche, couteau à dépecer, canne à pêche...), objets d'un ensemble d'équipement. Clic sur une ligne : cocher / décocher. Seuls les objets cochés sont mis en vente. Clic droit : ne plus jamais proposer cet objet."] = "Listet die Gegenstände in deinen Taschen auf, die das Auktionshaus akzeptiert, mit einem Preis für jeden. Nie angeboten werden: gebundene Gegenstände, weiße oder graue Ausrüstung, Berufswerkzeuge (Spitzhacke, Kürschnermesser, Angelrute ...), Gegenstände eines Ausrüstungssets. Klick auf eine Zeile: an- / abwählen. Nur angewählte Gegenstände werden eingestellt. Rechtsklick: diesen Gegenstand nie mehr anbieten.",
    ["Lit l'historique de butin du jeu : rien n'est envoyé aux autres joueurs."] = "Liest den Beuteverlauf des Spiels: Es wird nichts an andere Spieler gesendet.",
