    ["Par défaut : %s"] = "Standard: %s",
    ["Par défaut, elle n'apparaît qu'en groupe et en combat."] = "Standardmäßig erscheint sie nur in der Gruppe und im Kampf.",
    ["Par heure"] = "Pro Stunde",
    ["Parle à un marchand : le tri est déjà fait."] = "Sprich mit einem Händler: Die Sortierung ist schon erledigt.",
    ["Parler à un PNJ, ouvrir un coffre, cueillir une plante, dépecer une bête."] = "Mit einem NSC sprechen, eine Truhe öffnen, eine Pflanze pflücken, ein Tier häuten.",
    ["Pas de description."] = "Keine Beschreibung.",
    ["Pas de quête pour toi dans ce donjon"] = "Keine Quest für dich in diesem Dungeon",
    ["Pas interruptible"] = "Nicht unterbrechbar",
    ["Pas sûr ? Garde Recommandé : c'est le réglage de départ. Les pages suivantes montrent les principaux interrupteurs de chaque fonction, réglés selon ton mode."] = "Unsicher? Behalte Empfohlen: das ist die Starteinstellung. Die nächsten Seiten zeigen die wichtigsten Schalter jeder Funktion, passend zu deinem Modus eingestellt.",
    ["Passe"] = "Passen",
    ["Passer la visite"] = "Rundgang überspringen",
    ["Pavé %s"] = "Feld %s",
    ["Pendant que l'HDV est ouvert, cette touche fait comme un clic sur « Mettre en vente » : une mise en vente par appui. Ailleurs, la touche garde son rôle habituel. « Aucune » : seulement le bouton (ou une macro « /click PlatyplusAHPost »)."] = "Solange das Auktionshaus geöffnet ist, wirkt diese Taste wie ein Klick auf „Einstellen“: ein Einstellen pro Tastendruck. Sonst behält die Taste ihre übliche Rolle. „Keine“: nur die Schaltfläche (oder ein Makro „/click PlatyplusAHPost“).",
    ["Personnage"] = "Charakter",
    ["Personnage : tes cases d'équipement (celles du jeu : clic droit sur un bijou pour l'utiliser, Alt pour les objets de rechange), le niveau d'objet sur chaque case, ton personnage en 3D à tourner à la souris et tes caractéristiques calculées par le jeu (survol : le détail). Réputation : clic sur une faction pour la suivre sur la barre d'expérience ou lui déclarer la guerre. Coupé : la fenêtre du jeu revient."] = "Charakter: deine Ausrüstungsfelder (die des Spiels: Rechtsklick auf ein Schmuckstück zum Benutzen, Alt für Ersatzgegenstände), die Gegenstandsstufe auf jedem Feld, deine 3D-Figur zum Drehen mit der Maus und deine vom Spiel berechneten Werte (Überfahren: das Detail). Ruf: Klick auf eine Fraktion, um sie auf der Erfahrungsleiste zu verfolgen oder ihr den Krieg zu erklären. Aus: Das Spielfenster kommt zurück.",
    ["Personne n'en vend (x prix marchand)"] = "Niemand verkauft ihn (x Händlerpreis)",
    ["Personne n'en vend en ce moment."] = "Im Moment verkauft niemand welche.",
    ["Personne n'en vend et l'objet n'a pas de prix marchand : mets-le en vente à la main."] = "Niemand verkauft ihn und der Gegenstand hat keinen Händlerpreis: stelle ihn von Hand ein.",
    ["Perte"] = "Verlust",
    ["Pièce la plus usée"] = "Am stärksten abgenutztes Teil",
    ["Pièces vendues par visite"] = "Verkaufte Teile pro Besuch",
    ["Places libres"] = "Freie Plätze",
    ["Places libres dans les sacs"] = "Freie Taschenplätze",
    ["Plantes"] = "Pflanzen",
    ["Plates"] = "Plaketten",
    ["Plates Platyplus"] = "Platyplus-Namensplaketten",
    ["Plates colorées par la menace"] = "Plaketten in Bedrohungsfarben",
    ["Plates des mobs"] = "Gegner-Plaketten",
    ["Plates non ciblées"] = "Plaketten ohne Ziel",
    ["Platyplus - vente"] = "Platyplus - Verkauf",
    ["Platyplus est réglé pour bien démarrer. Voici l'essentiel à retenir."] = "Platyplus ist für einen guten Start eingestellt. Hier das Wichtigste zum Merken.",
    ["Platyplus rassemble en un seul addon les petits plus qui rendent le jeu plus fluide : une touche qui fait presque tout, des alertes de combat lisibles, le butin et la vente sans clics, et des fenêtres plus claires."] = "Platyplus vereint in einem einzigen Addon die kleinen Extras, die das Spiel flüssiger machen: eine Taste, die fast alles erledigt, lesbare Kampfwarnungen, Beute und Verkauf ohne Klicks und übersichtlichere Fenster.",
    ["Plus c'est long, plus le dépôt demandé par l'HDV est élevé (il est rendu si l'objet se vend)."] = "Je länger, desto höher die vom Auktionshaus verlangte Anzahlung (sie wird erstattet, wenn der Gegenstand sich verkauft).",
    ["Plus la valeur est grande, plus tu peux éloigner la caméra (2,6 = maximum du jeu)."] = "Je größer der Wert, desto weiter kannst du die Kamera wegbewegen (2,6 = Maximum des Spiels).",
    ["Plus tard"] = "Später",
    ["Points de combo"] = "Combopunkte",
    ["Portée d'interaction"] = "Interaktionsreichweite",
    ["Position"] = "Position",
    ["Position de ton personnage sur la carte de la zone (de 0 à 100). Indisponible dans certaines instances."] = "Position deiner Figur auf der Zonenkarte (von 0 bis 100). In manchen Instanzen nicht verfügbar.",
    ["Pour ta classe"] = "Für deine Klasse",
    ["Pour toi (l'HDV garde 5 %)"] = "Für dich (das Auktionshaus behält 5 %)",
    ["Pourcentage de mana sous lequel l'alerte se déclenche : à 20 %, un healer à 6 800 de mana maximum est à sec sous 1 360."] = "Manaprozentsatz, unter dem die Warnung ausgelöst wird: Bei 20 % hat ein Heiler mit höchstens 6.800 Mana unter 1.360 kein Mana mehr.",
    ["Pourcentage du niveau. Clic sur la valeur : XP par heure, temps avant le niveau, monstres restants. Survol : tout le détail de la session."] = "Prozentsatz der Stufe. Klick auf den Wert: EP pro Stunde, Zeit bis zur nächsten Stufe, verbleibende Monster. Überfahren: das ganze Detail der Sitzung.",
    ["Prendre : %s"] = "Nehmen: %s",
    ["Presque noir par défaut."] = "Standardmäßig fast schwarz.",
    ["Prix connus"] = "Bekannte Preise",
    ["Prix dans les infobulles"] = "Preise in Tooltips",
    ["Prix de l'HDV"] = "Auktionshaus-Preise",
    ["Prix de l'objet fabriqué à l'HDV, coût de chaque composant (le moins cher entre l'HDV et le marchand), puis ce que tu gagnes ou perds en fabriquant pour revendre (l'HDV garde 5 % de la vente). Les prix d'achat des marchands (fils, fioles...) sont relevés quand tu les visites."] = "Auktionshaus-Preis des hergestellten Gegenstands, Kosten jeder Komponente (das Günstigere aus Auktionshaus und Händler), dann was du beim Herstellen zum Weiterverkauf gewinnst oder verlierst (das Auktionshaus behält 5 % des Verkaufs). Die Einkaufspreise der Händler (Fäden, Fläschchen ...) werden erfasst, wenn du sie besuchst.",
    ["Prix de l'objet relevé %s."] = "Gegenstandspreis erfasst %s.",
    ["Prix à l'HDV"] = "Preis im Auktionshaus",
    ["Prochain niveau dans"] = "Nächste Stufe in",
    ["Prochaine récompense : rang %d"] = "Nächste Belohnung: Rang %d",
    ["Procs"] = "Procs",
    ["Progression « 3/8 »"] = "Fortschritt „3/8“",
    ["Précédent"] = "Zurück",
    ["Prévient quand une pièce de ton équipement est presque cassée, pour penser à réparer."] = "Warnt, wenn ein Ausrüstungsteil fast kaputt ist, damit du ans Reparieren denkst.",
    ["Prêt à jouer"] = "Bereit zum Spielen",
    ["Prêtre"] = "Priester",
    ["Puissance astrale"] = "Astrale Macht",
    ["Puissance runique"] = "Runenmacht",
    ["Puissance sacrée"] = "Heilige Kraft",
    ["QUÊTES EN COURS"] = "LAUFENDE QUESTS",
    ["QUÊTES PROPOSÉES"] = "ANGEBOTENE QUESTS",
    ["Qualité maximale vendue"] = "Maximal verkaufte Qualität",
    ["Quand il n'y a plus de quête à accepter ni à rendre, la touche choisit la première option disponible du PNJ (formation, marchand, maître de vol...). Coupe-le si tu préfères choisir toi-même."] = "Wenn es keine Quests mehr anzunehmen oder abzugeben gibt, wählt die Taste die erste verfügbare Option des NPCs (Ausbildung, Händler, Flugmeister ...). Schalte es aus, wenn du lieber selbst wählst.",
    ["Quand personne ne vend l'objet : dernier prix vu à l'HDV ces 14 derniers jours, sinon le prix du marchand multiplié par ce nombre. Un objet sans prix marchand et jamais vu n'est pas proposé."] = "Wenn niemand den Gegenstand verkauft: letzter im Auktionshaus gesehener Preis der letzten 14 Tage, sonst der Händlerpreis mal diese Zahl. Ein Gegenstand ohne Händlerpreis, der nie gesehen wurde, wird nicht angeboten.",
    ["Quand quelqu'un écrit ton nom (canaux, groupe, guilde...)."] = "Wenn jemand deinen Namen schreibt (Kanäle, Gruppe, Gilde ...).",
    ["Quand ta Volée de coups (ou Coup de bouclier, Coup de pied, Contresort, Horion de terre) est prête et utilisable dans ta posture : fonce !"] = "Wenn dein Zuschlagen (oder Schildschlag, Tritt, Gegenzauber, Erdschock) bereit und in deiner Haltung einsetzbar ist: los!",
    ["Quand tu as le buff Maîtrise du blocage, son icône apparaît à droite des alertes de proc (seule au centre s'il n'y a pas d'alerte) et disparaît dès que le buff finit ou que tu as bloqué avec ta dernière charge. En combat le jeu cache tes buffs : l'addon repère alors celui qui apparaît juste après ton clic. Elle suit la taille et la position des alertes. /pp proc donne l'état."] = "Wenn du den Buff Schildblock hast, erscheint sein Symbol rechts von den Proc-Warnungen (allein in der Mitte, wenn es keine Warnung gibt) und verschwindet, sobald der Buff endet oder du mit deiner letzten Ladung geblockt hast. Im Kampf verbirgt das Spiel deine Buffs: Das Addon erkennt dann den, der direkt nach deinem Klick erscheint. Es folgt Größe und Position der Warnungen. /pp proc zeigt den Zustand.",
    ["Quand tu as une cible, les autres barres passent à cette opacité. 100 % = pas d'effet ; 50 % = ta cible ressort nettement."] = "Wenn du ein Ziel hast, gehen die anderen Leisten auf diese Deckkraft. 100 % = kein Effekt; 50 % = dein Ziel sticht deutlich hervor.",
    ["Quand tu ouvres une quête dans le journal à côté de la carte : d'abord ce qu'il faut faire (le but et chaque objectif avec sa progression), puis les récompenses, et l'histoire repliée en bas (clic pour la déplier). Fond sombre, texte clair. Éteint : la page du jeu, sur parchemin."] = "Wenn du im Journal neben der Karte eine Quest öffnest: zuerst, was zu tun ist (das Ziel und jede Aufgabe mit ihrem Fortschritt), dann die Belohnungen, und die Geschichte eingeklappt unten (Klick zum Ausklappen). Dunkler Hintergrund, heller Text. Aus: die Spielseite auf Pergament.",
    ["Quand un sort devient utilisable (Fulgurance après une esquive, un sort qui brille...), son icône apparaît en grand sous ton personnage avec la touche à presser."] = "Wenn ein Zauber einsetzbar wird (Überwältigen nach einem Ausweichen, ein leuchtender Zauber ...), erscheint sein Symbol groß unter deiner Figur mit der zu drückenden Taste.",
    ["Quand une fenêtre de PNJ est ouverte, la même touche accepte la quête, la rend ou fait avancer le dialogue, une étape à chaque appui. Les confirmations de Blizzard (choix de récompense, coût...) restent actives."] = "Wenn ein NPC-Fenster offen ist, nimmt dieselbe Taste die Quest an, gibt sie ab oder führt den Dialog weiter, ein Schritt pro Druck. Die Bestätigungen von Blizzard (Belohnungswahl, Kosten ...) bleiben aktiv.",
    ["Quand une quête de ton journal a un objet à utiliser (torche, fiole...) et que tu es là où il faut l'utiliser, la touche utilise cet objet. Maj + touche interagit quand même (pour parler à un PNJ à côté). En combat, la touche loote ou interagit (jamais le mob vivant sous la souris) et l'objet passe sur Maj + touche."] = "Wenn eine Quest deines Journals einen zu benutzenden Gegenstand hat (Fackel, Fläschchen ...) und du dort bist, wo er benutzt werden muss, benutzt die Taste diesen Gegenstand. Umschalt + Taste interagiert trotzdem (um mit einem NPC in der Nähe zu sprechen). Im Kampf plündert oder interagiert die Taste (nie mit dem lebenden Gegner unter der Maus) und der Gegenstand wandert auf Umschalt + Taste.",
    ["Quand une quête propose plusieurs objets, c'est toujours toi qui choisis : Platyplus ne prend jamais une récompense à ta place."] = "Bietet eine Quest mehrere Gegenstände, wählst immer du: Platyplus nimmt nie eine Belohnung für dich.",
    ["Quand une quête propose plusieurs objets, chacun devient une grande carte : rareté, niveau d'objet, caractéristiques, prix de vente et comparaison avec ton équipement. La carte « Recommandée » est un conseil (la pièce qui améliore le plus ton équipement, sinon la plus chère à la vente) : rien n'est choisi tant que tu n'as pas cliqué. Clic pour choisir, double-clic (ou ta touche) pour rendre la quête. Maintiens Maj en ouvrant la fenêtre pour garder la fenêtre classique."] = "Bietet eine Quest mehrere Gegenstände, wird jeder zu einer großen Karte: Seltenheit, Gegenstandsstufe, Werte, Verkaufspreis und Vergleich mit deiner Ausrüstung. Die Karte „Empfohlen“ ist ein Rat (das Teil, das deine Ausrüstung am meisten verbessert, sonst das beim Verkauf teuerste): Es wird nichts gewählt, bis du klickst. Klick zum Wählen, Doppelklick (oder deine Taste) zum Abgeben der Quest. Halte Umschalt beim Öffnen des Fensters, um das klassische Fenster zu behalten.",
    ["Quelqu'un est sur le point de prendre ou de perdre l'aggro."] = "Jemand nimmt oder verliert gleich die Aggro.",
    ["Quelques réglages du jeu rendent le jeu à la touche plus confortable. Platyplus n'y touche que si tu le demandes : tes valeurs d'origine sont gardées, et « Rétablir » les remet."] = "Einige Spieleinstellungen machen das Spielen mit der Taste bequemer. Platyplus rührt sie nur an, wenn du es willst: Deine ursprünglichen Werte werden gemerkt, und „Wiederherstellen“ setzt sie zurück.",
    ["Quels sorts déclenchent une alerte. Ils doivent être rangés sur une de tes barres."] = "Welche Zauber eine Warnung auslösen. Sie müssen auf einer deiner Leisten liegen.",
    ["Questie met aussi ses icônes sur les plates : on ne garde que les nôtres, avec la progression."] = "Questie setzt seine Symbole auch auf die Plaketten: Wir behalten nur unsere, mit dem Fortschritt.",
    ["Quête"] = "Quest",
    ["Quête : %s"] = "Quest: %s",
    ["Quête terminée"] = "Quest abgeschlossen",
    ["Quête terminée  ·  %s"] = "Quest abgeschlossen  ·  %s",
    ["Quête, consommables, artisanat, équipement, divers et poubelle, chacun sous son titre."] = "Quest, Verbrauchsgüter, Handwerkswaren, Ausrüstung, Sonstiges und Plunder, jedes unter seinem Titel.",
    ["Quêtes"] = "Quests",
    ["Quêtes auto"] = "Auto-Quests",
    ["Quêtes et dialogues en grand texte ; les récompenses au choix en grandes cartes, la meilleure pour toi mise en avant."] = "Quests und Dialoge in großer Schrift; die wählbaren Belohnungen als große Karten, die beste für dich hervorgehoben.",
    ["Quêtes et mobs spéciaux."] = "Quests und besondere Gegner.",
    ["Quêtes faites : %d sur %d"] = "Abgeschlossene Quests: %d von %d",
    ["Quêtes, sacs et personnage dans des fenêtres Platyplus, en grand ; niveau d'objet."] = "Quests, Taschen und Charakter in großen Platyplus-Fenstern; Gegenstandsstufe.",
    ["Raccourcit le nom des canaux devant chaque message : numéro seul pour les canaux publics, G (guilde), O (officiers), Gr (groupe), R (raid), AR (avertissement de raid), I (instance)."] = "Kürzt die Kanalnamen vor jeder Nachricht: nur die Nummer für öffentliche Kanäle, G (Gilde), O (Offiziere), P (Gruppe), R (Schlachtzug), RW (Schlachtzugswarnung), I (Instanz).",
    ["Rage"] = "Wut",
    ["Ralentit"] = "Verlangsamt",
    ["Ralentit les attaques"] = "Verlangsamt Angriffe",
    ["Ramassage"] = "Plündern",
    ["Ramassage instantané, étincelles sur ce qui se ramasse, butin affiché à l'écran et jets de dés en groupe."] = "Sofortiges Plündern, Funken auf allem, was sich einsammeln lässt, Beute auf dem Bildschirm und Würfe in der Gruppe.",
    ["Ramasse tout le contenu d'un cadavre ou d'un coffre dès son ouverture, sans fenêtre de loot. Maintiens la touche de loot manuel du jeu (Maj par défaut) pour afficher la fenêtre normale."] = "Plündert den ganzen Inhalt einer Leiche oder Truhe, sobald sie sich öffnet, ohne Beutefenster. Halte die manuelle Plündertaste des Spiels (standardmäßig Umschalt), um das normale Fenster anzuzeigen.",
    ["Rang %d"] = "Rang %d",
    ["Rang %s"] = "Rang %s",
    ["Rang JcJ indisponible"] = "PvP-Rang nicht verfügbar",
    ["Rang maximum"] = "Höchster Rang",
    ["Rang maximum de la saison"] = "Höchster Rang der Saison",
    ["Range le contenu de tes sacs (même action que /pp sort)."] = "Sortiert den Inhalt deiner Taschen (gleiche Aktion wie /pp sort).",
    ["Ranger (inactive)"] = "Inaktiv setzen",
    ["Ranger par type"] = "Nach Typ ordnen",
    ["Rappel de buffs"] = "Buff-Erinnerung",
    ["Rappel de buffs : ceux que ton groupe peut te donner et qui te manquent ; pour un guerrier, le Cri de guerre en combat."] = "Buff-Erinnerung: die Buffs, die deine Gruppe dir geben kann und die dir fehlen; für einen Krieger der Schlachtruf im Kampf.",
    ["Rare"] = "Selten",
    ["Recalcule la liste à partir du contenu actuel de tes sacs."] = "Berechnet die Liste aus dem aktuellen Inhalt deiner Taschen neu.",
    ["Recharge l'interface du jeu (/reload) pour appliquer la langue. Impossible en combat."] = "Lädt die Spieloberfläche neu (/reload), um die Sprache anzuwenden. Im Kampf nicht möglich.",
    ["Recharge l'interface pour passer Platyplus dans cette langue."] = "Lade die Oberfläche neu, um Platyplus auf diese Sprache umzustellen.",
    ["Recharge l'interface, pour appliquer « Style Platyplus »."] = "Lädt die Oberfläche neu, um „Platyplus-Stil“ anzuwenden.",
    ["Recharger l'interface"] = "Oberfläche neu laden",
    ["Recherche des prix..."] = "Preissuche...",
    ["Recommandé"] = "Empfohlen",
    ["Recommandé, Complet, Immersif ou Minimal : un clic règle tout d'un coup, et tu changes ensuite ce que tu veux."] = "Empfohlen, Komplett, Immersiv oder Minimal: Ein Klick stellt alles auf einmal ein, danach änderst du, was du willst.",
    ["Recommandée"] = "Empfohlen",
    ["Refermer après les jets"] = "Nach den Würfen schließen",
    ["Refuse automatiquement les invitations à rejoindre une guilde."] = "Lehnt Einladungen in eine Gilde automatisch ab.",
    ["Refuse automatiquement toute demande de duel."] = "Lehnt jede Duellanfrage automatisch ab.",
    ["Refuser"] = "Ablehnen",
    ["Refuser les duels"] = "Duelle ablehnen",
    ["Refuser les invitations de guilde"] = "Gildeneinladungen ablehnen",
    ["Refusé : %s"] = "Abgelehnt: %s",
    ["Relance la visite montrée à la première installation : une page par grande fonction, avec ses réglages principaux (aussi : /pp bienvenue)."] = "Startet den bei der ersten Installation gezeigten Rundgang neu: eine Seite pro wichtiger Funktion, mit ihren Haupteinstellungen (auch: /pp bienvenue).",
    ["Relève d'un coup le prix de tout ce qui est en vente à l'HDV (quelques secondes). Le serveur ne l'autorise qu'une fois toutes les 15 min. Coupé : bouton « Scan complet » du panneau de l'HDV, ou /pp hdv complet."] = "Aktualisiert auf einmal den Preis von allem, was im Auktionshaus angeboten wird (einige Sekunden). Der Server erlaubt es nur alle 15 Min. einmal. Aus: Schaltfläche „Vollständiger Scan“ im Auktionshaus-Panel oder /pp hdv complet.",
    ["Remet absolument tout à zéro, y compris tes listes « Ne jamais vendre » et « Toujours vendre »."] = "Setzt absolut alles zurück, auch deine Listen „Nie verkaufen“ und „Immer verkaufen“.",
    ["Remet chaque réglage du jeu à la valeur qu'il avait avant que Platyplus le change."] = "Setzt jede Spieleinstellung auf den Wert zurück, den sie hatte, bevor Platyplus sie geändert hat.",
    ["Remet le look et toutes les couleurs des plates comme à l'installation (pas le rôle)."] = "Setzt Aussehen und alle Farben der Plaketten auf den Zustand bei der Installation zurück (nicht die Rolle).",
    ["Remet les réglages à leur valeur par défaut. Chaque bouton demande une confirmation : reclique dessus dans les 3 secondes."] = "Setzt die Einstellungen auf ihren Standardwert zurück. Jede Schaltfläche verlangt eine Bestätigung: Klicke innerhalb von 3 Sekunden erneut darauf.",
    ["Remet tous les réglages à zéro (touche, loot, vente, confort...) mais conserve tes listes « Ne jamais vendre » et « Toujours vendre »."] = "Setzt alle Einstellungen zurück (Taste, Beute, Verkauf, Komfort ...), behält aber deine Listen „Nie verkaufen“ und „Immer verkaufen“.",
    ["Remettre (aucune)"] = "Zurücksetzen (keine)",
    ["Remettre F"] = "Auf F zurücksetzen",
    ["Remettre active"] = "Wieder aktivieren",
    ["Remettre en place"] = "Zurücksetzen",
    ["Remettre l'icône en place"] = "Symbol zurücksetzen",
    ["Remettre la fenêtre en place"] = "Fenster zurücksetzen",
    ["Remplace la fenêtre de dialogue des PNJ par une fenêtre Platyplus en grand texte."] = "Ersetzt das Dialogfenster der NSCs durch ein Platyplus-Fenster in großer Schrift.",
    ["Remplace la fiche du personnage du jeu (touche C)."] = "Ersetzt das Charakterfenster des Spiels (Taste C).",
    ["Remplace les fenêtres de chat du jeu par une fenêtre Platyplus : onglets Chat / Guilde / Groupe / Chuchot. / Canaux / Jeu (butin, expérience, système), recherche."] = "Ersetzt die Chatfenster des Spiels durch ein Platyplus-Fenster: Reiter Chat / Gilde / Gruppe / Flüstern / Kanäle / Spiel (Beute, Erfahrung, System), Suche.",
    ["Remplace les sacs séparés du jeu (touche B)."] = "Ersetzt die einzelnen Taschen des Spiels (Taste B).",
    ["Rend l'alerte plus ou moins transparente. Exemple : 60 % pour qu'elle gêne moins la vue en plein combat."] = "Macht die Warnung mehr oder weniger durchsichtig. Beispiel: 60 %, damit sie mitten im Kampf die Sicht weniger stört.",
    ["Replace l'alerte sous ton personnage."] = "Setzt die Warnung unter deine Figur zurück.",
    ["Replace l'icône à son emplacement par défaut (en haut à droite)."] = "Setzt das Symbol an seine Standardposition zurück (oben rechts).",
    ["Replace la barre sous ton personnage."] = "Setzt die Leiste unter deine Figur zurück.",
    ["Replace la barre à sa place d'origine (à gauche sous le centre de l'écran)."] = "Setzt die Leiste an ihren ursprünglichen Platz zurück (links, unter der Bildschirmmitte).",
    ["Replace la fenêtre de chat Platyplus par-dessus l'emplacement du chat du jeu."] = "Setzt das Platyplus-Chatfenster an die Stelle des Spielchats zurück.",
    ["Replace la fenêtre de quête à gauche de l'écran, comme au premier jour."] = "Setzt das Questfenster links auf den Bildschirm zurück, wie am ersten Tag.",
    ["Replace la fenêtre des sacs en bas à droite de l'écran."] = "Setzt das Taschenfenster unten rechts auf den Bildschirm zurück.",
    ["Replace la fenêtre du personnage à gauche de l'écran."] = "Setzt das Charakterfenster links auf den Bildschirm zurück.",
    ["Replace la rangée au-dessus de ton personnage."] = "Setzt die Reihe über deine Figur zurück.",
    ["Replace le flux à son emplacement par défaut."] = "Setzt den Feed an seine Standardposition zurück.",
    ["Repousse"] = "Stößt zurück",
    ["Repérer les rares"] = "Seltene erkennen",
    ["Repérer les élites et les boss"] = "Elite-Gegner und Bosse erkennen",
    ["Ressource"] = "Ressource",
    ["Reste"] = "Verbleibend",
    ["Revoir la visite guidée"] = "Rundgang noch einmal ansehen",
    ["Rien ne t'attaque."] = "Nichts greift dich an.",
    ["Rien ne t'échappe : ce que tu peux ramasser brille quand tu t'en approches."] = "Dir entgeht nichts: Was du aufheben kannst, glänzt, wenn du dich näherst.",
    ["Rien à mettre en vente"] = "Nichts einzustellen",
    ["Rien à proposer : aucun objet de tes sacs ne peut aller à l'HDV (objets liés, équipement blanc ou gris, outils de métier, ou objets exclus)."] = "Nichts vorzuschlagen: kein Gegenstand in deinen Taschen kann ins Auktionshaus (gebundene Gegenstände, weiße oder graue Ausrüstung, Berufswerkzeuge oder ausgeschlossene Gegenstände).",
    ["Rien à vendre (pas d'objet fabriqué)"] = "Nichts zu verkaufen (kein hergestellter Gegenstand)",
    ["Rien à vendre."] = "Nichts zu verkaufen.",
    ["Rond"] = "Rund",
    ["Rugissement"] = "Brüllen",
    ["Runes"] = "Runen",
    ["RÉCOMPENSES"] = "BELOHNUNGEN",
    ["Récompense"] = "Belohnung",
    ["Récompenses en grandes cartes"] = "Belohnungen als große Karten",
    ["Récupère objets et argent dès que tu ouvres la boîte aux lettres."] = "Nimmt Gegenstände und Geld, sobald du den Briefkasten öffnest.",
    ["Réduit au silence"] = "Zum Schweigen gebracht",
    ["Réglage du jeu (Options > Plates d'unités). Grande = 25 % de plus que la taille normale, Énorme = 60 %. Se change hors combat."] = "Spieleinstellung (Optionen > Namensplaketten). Groß = 25 % größer als die Normalgröße, Riesig = 60 %. Außerhalb des Kampfes änderbar.",
    ["Réglage du jeu (et non de Platyplus) : il est conservé par le jeu."] = "Spieleinstellung (nicht von Platyplus): Sie wird vom Spiel gespeichert.",
    ["Réglage du jeu. Fine : 13 px de haut ; Épaisse : 20 px, bien plus lisible en combat ; Bloc : épaisse, et la barre d'incantation aussi. Se change hors combat."] = "Spieleinstellung. Dünn: 13 px hoch; Dick: 20 px, im Kampf viel besser lesbar; Block: dick, und die Zauberleiste ebenfalls. Außerhalb des Kampfes änderbar.",
    ["Réglages du jeu"] = "Spieleinstellungen",
    ["Réglages du jeu recommandés, en un clic."] = "Empfohlene Spieleinstellungen mit einem Klick.",
    ["Réglages personnalisés, à partir du mode %s. Choisir un mode remet tous ses interrupteurs."] = "Eigene Einstellungen, ausgehend vom Modus %s. Die Wahl eines Modus setzt alle seine Schalter zurück.",
    ["Réglages rapides"] = "Schnelleinstellungen",
    ["Réglages recommandés"] = "Empfohlene Einstellungen",
    ["Régler le recul maximum de la caméra"] = "Maximale Kamerazoomweite einstellen",
    ["Réinitialisation"] = "Zurücksetzen",
    ["Réparation"] = "Reparatur",
    ["Répare chez un marchand (Platyplus peut réparer tout seul : voir les options)."] = "Repariert bei einem Händler (Platyplus kann von selbst reparieren: siehe Optionen).",
    ["Répare tout ton équipement à l'ouverture d'un marchand qui sait réparer. Le coût s'affiche dans le flux."] = "Repariert deine gesamte Ausrüstung, wenn du einen Händler öffnest, der reparieren kann. Die Kosten erscheinen im Feed.",
    ["Réparer automatiquement"] = "Automatisch reparieren",
    ["Réparer chez les marchands"] = "Beim Händler reparieren",
    ["Réparé"] = "Repariert",
    ["Réputation"] = "Ruf",
    ["Réputations indisponibles sur ce client."] = "Rufe auf diesem Client nicht verfügbar.",
    ["Résistance : %s"] = "Widerstand: %s",
    ["Résistances"] = "Widerstände",
    ["Rétablir mes anciens réglages"] = "Meine alten Einstellungen wiederherstellen",
    ["Rétablit la touche par défaut de Platyplus ((aucune))."] = "Stellt die Standardtaste von Platyplus wieder her ((keine)).",
    ["Rétablit la touche par défaut de Platyplus (F)."] = "Stellt die Standardtaste von Platyplus wieder her (F).",
    ["S'il te manque en combat : son icône et sa touche, comme une alerte de proc."] = "Fehlt er dir im Kampf: sein Symbol und seine Taste, wie eine Proc-Warnung.",
    ["S'ouvre avec la touche des sacs, chez le marchand, à la banque ou au courrier."] = "Öffnet sich mit der Taschentaste, beim Händler, bei der Bank oder am Briefkasten.",
    ["Sacs"] = "Taschen",
    ["Saison %d"] = "Saison %d",
    ["Sans Alt, et gardé d'une session à l'autre."] = "Ohne Alt, und von einer Sitzung zur nächsten gespeichert.",
    ["Sans appuyer sur rien. Maintiens Maj en parlant au PNJ pour faire une pause."] = "Ohne etwas zu drücken. Halte Umschalt, während du mit dem NPC sprichst, um zu pausieren.",
    ["Sans rang"] = "Ohne Rang",
    ["Scan complet automatique"] = "Automatischer vollständiger Scan",
    ["Se remplit à la vitesse de ton arme et repart à chaque coup blanc (le jeu le signale lui-même). Le temps restant s'affiche à droite. Elle devient dorée quand Frappe héroïque ou Enchaînement attend le prochain coup, et pâlit quand ta cible est hors de portée."] = "Füllt sich in der Geschwindigkeit deiner Waffe und startet bei jedem normalen Angriff neu (das Spiel meldet ihn selbst). Die Restzeit steht rechts. Sie wird golden, wenn Heldenhafter Stoß oder Spalten auf den nächsten Treffer wartet, und verblasst, wenn dein Ziel außer Reichweite ist.",
    ["Se vend le plus cher"] = "Teuerster Verkaufspreis",
    ["Sens d'empilement"] = "Stapelrichtung",
    ["Ses réglages"] = "Seine Einstellungen",
    ["Session"] = "Sitzung",
    ["Seuil d'alerte"] = "Warnschwelle",
    ["Seul, tu sais déjà que les mobs te tapent : la fenêtre ne s'affiche pas."] = "Allein weißt du schon, dass Gegner dich angreifen: Das Fenster wird nicht angezeigt.",
    ["Seulement en combat"] = "Nur im Kampf",
    ["Seulement en combat."] = "Nur im Kampf.",
    ["Seulement en groupe"] = "Nur in einer Gruppe",
    ["Si l'addon Threat Plates est actif, il remplace les plates du jeu : désactive-le pour voir celles-ci. Les cadavres à fouiller ont déjà leurs étincelles (onglet Butin). /pp plates : ce que voit chaque plate."] = "Ist das Addon Threat Plates aktiv, ersetzt es die Namensplaketten des Spiels: Deaktiviere es, um diese zu sehen. Plünderbare Leichen haben ihre Funken schon (Reiter Beute). /pp plates: was jede Plakette sieht.",
    ["Si le marchand t'en donne autant ou plus, l'objet n'est pas mis en vente."] = "Gibt dir der Händler ebenso viel oder mehr, wird der Gegenstand nicht eingestellt.",
    ["Si ta guilde l'autorise, la réparation est payée par la banque de guilde ; sinon, avec ton argent."] = "Erlaubt es deine Gilde, wird die Reparatur von der Gildenbank bezahlt; sonst mit deinem Geld.",
    ["Si tu fais des dégâts : vert quand le mob t'ignore, orange quand ça se joue, rouge quand il t'attaque. Si tu tankes, c'est l'inverse : rouge, il t'échappe."] = "Wenn du Schaden machst: grün, wenn der Gegner dich ignoriert, orange, wenn es knapp ist, rot, wenn er dich angreift. Wenn du tankst, ist es umgekehrt: rot, er entkommt dir.",
    ["Soins (pas interruptible)"] = "Heilzauber (nicht unterbrechbar)",
    ["Son quand ta cible incante"] = "Ton, wenn dein Ziel zaubert",
    ["Son à l'apparition"] = "Ton beim Erscheinen",
    ["Sorts ajoutés"] = "Hinzugefügte Zauber",
    ["Sorts ignorés"] = "Ignorierte Zauber",
    ["Sorts qui brillent"] = "Leuchtende Zauber",
    ["Sorts réactifs de ma classe"] = "Reaktive Zauber meiner Klasse",
    ["Sorts surveillés"] = "Überwachte Zauber",
    ["Souris %s"] = "Maus %s",
    ["Sous le seuil, la barre devient rouge et clignote."] = "Unter der Schwelle wird die Leiste rot und blinkt.",
    ["Spé 2"] = "Spez. 2",
    ["Style Platyplus"] = "Platyplus-Stil",
    ["Styles prêts à l'emploi :"] = "Fertige Stile:",
    ["Suivant"] = "Weiter",
    ["Suivre aussi les /roll"] = "Auch /roll verfolgen",
    ["Suivre les jets de butin"] = "Beutewürfe verfolgen",
    ["Suivre sur la barre"] = "Auf der Leiste verfolgen",
    ["Sur ce personnage"] = "Auf diesem Charakter",
    ["Sur la fiche du personnage"] = "Im Charakterfenster",
    ["Sur la plate : ta progression de quête (« 3/8 ») et l'étiquette « Rare »."] = "Auf der Plakette: dein Questfortschritt („3/8“) und das Etikett „Selten“.",
    ["Sur les grandes cartes de l'accueil, la tranche de niveau prend la même couleur et une pastille « À ton niveau » ou « Bientôt » s'ajoute. La première fois que tu ouvres l'accueil, il défile jusqu'aux donjons de ton niveau."] = "Auf den großen Karten der Startseite hat der Stufenabschnitt dieselbe Farbe, und ein Abzeichen „Auf deiner Stufe“ oder „Bald“ kommt hinzu. Beim ersten Öffnen der Startseite scrollt sie zu den Dungeons deiner Stufe.",
    ["Sur les objets des sacs"] = "Auf den Gegenständen in den Taschen",
    ["Système"] = "System",
    ["Sûr ? (re-clique)"] = "Sicher? (nochmal klicken)",
    ["Ta cible"] = "Dein Ziel",
    ["Ta cible esquive : l'icône de Fulgurance apparaît avec « 3 » dessous si elle est sur la touche 3."] = "Dein Ziel weicht aus: Das Symbol von Überwältigen erscheint mit „3“ darunter, wenn es auf Taste 3 liegt.",
    ["Ta position sur la carte de la zone."] = "Deine Position auf der Zonenkarte.",
    ["Ta touche"] = "Deine Taste",
    ["Tabard"] = "Wappenrock",
    ["Taille"] = "Größe",
    ["Taille de l'icône"] = "Symbolgröße",
    ["Taille de la fenêtre"] = "Fenstergröße",
    ["Taille des messages dans la fenêtre de chat Platyplus."] = "Größe der Nachrichten im Platyplus-Chatfenster.",
    ["Taille des plates"] = "Größe der Plaketten",
    ["Taille du texte"] = "Textgröße",
    ["Taille, nombre, animation et son des alertes."] = "Größe, Anzahl, Animation und Ton der Warnungen.",
    ["Taille, épaisseur, texture, transparence."] = "Größe, Dicke, Textur, Transparenz.",
    ["Tank : en haut, les mobs que tu n'as pas ou que tu perds. DPS : en haut, ceux qui te tapent. Par vie : impossible quand le jeu cache la vie des mobs (ordre d'arrivée dans ce cas)."] = "Tank: oben die Gegner, die du nicht hast oder verlierst. Schaden: oben die, die dich angreifen. Nach Leben: unmöglich, wenn das Spiel das Leben der Gegner verbirgt (dann Reihenfolge des Eintreffens).",
    ["Tank : il tape un allié. DPS/soins : il te tape."] = "Tank: Er greift einen Verbündeten an. Schaden/Heilung: Er greift dich an.",
    ["Tank : le mob te tape. DPS/soins : il ne te regarde pas."] = "Tank: Der Gegner greift dich an. Schaden/Heilung: Er beachtet dich nicht.",
    ["Tank : quand un mob qui te tapait part sur un allié, sa plate clignote pour que tu le reprennes (Provocation, Coup railleur...)."] = "Tank: Wenn ein Gegner, der dich angriff, auf einen Verbündeten losgeht, blinkt seine Plakette, damit du ihn zurückholst (Spott, Spöttischer Schlag ...).",
    ["Tank : seulement les mobs que je n'ai pas"] = "Tank: nur die Gegner, die ich nicht habe",
    ["Tank : un éclat rouge sur la ligne d'un mob qui te tapait et tape maintenant quelqu'un d'autre. Sans son."] = "Tank: ein roter Blitz auf der Zeile eines Gegners, der dich angriff und jetzt jemand anderen angreift. Ohne Ton.",
    ["Tape /pp ou clique sur l'icône Platyplus : chaque fonction a son interrupteur, et chaque réglage s'explique quand tu le survoles. Pour revoir cette visite : /pp bienvenue."] = "Tippe /pp oder klick auf das Platyplus-Symbol: Jede Funktion hat ihren Schalter, und jede Einstellung erklärt sich, wenn du darüberfährst. Um diesen Rundgang noch einmal zu sehen: /pp welcome.",
    ["Tapé par d'autres"] = "Von anderen getappt",
    ["Temps de jeu actif"] = "Aktive Spielzeit",
    ["Temps de réponse du serveur, en millisecondes."] = "Antwortzeit des Servers in Millisekunden.",
    ["Temps pendant lequel une ligne reste affichée avant de s'estomper."] = "Wie lange eine Zeile angezeigt bleibt, bevor sie ausblendet.",
    ["Temps restant"] = "Verbleibende Zeit",
    ["Temps écoulé · gagnant inconnu"] = "Zeit abgelaufen · Gewinner unbekannt",
    ["Terminer"] = "Fertig",
    ["Tes mots à masquer"] = "Deine zu verbergenden Wörter",
    ["Tes sacs à la suite dans une grille. Les cases sont celles du jeu : clic droit pour utiliser ou vendre, glisser pour déplacer, Maj-clic pour lier ou partager une pile. Exemple : tape « lin » dans Chercher, seules tes Étoffes de lin restent allumées. Tire le bandeau pour déplacer la fenêtre. Coupé : les sacs du jeu reviennent."] = "Deine Taschen nacheinander in einem Raster. Die Felder sind die des Spiels: Rechtsklick zum Benutzen oder Verkaufen, Ziehen zum Verschieben, Umschalt-Klick zum Verlinken oder Teilen eines Stapels. Beispiel: Tippe „lein“ in Suchen, nur dein Leinenstoff bleibt hell. Zieh den Titelbalken zum Verschieben des Fensters. Aus: Die Spieltaschen kommen zurück.",
    ["Tester"] = "Testen",
    ["Texte dans la couleur du canal"] = "Text in der Kanalfarbe",
    ["Texte de statut du jeu : écrit les valeurs exactes sur les barres de vie et de ressource."] = "Statustext des Spiels: schreibt die genauen Werte auf die Leben- und Ressourcenleisten.",
    ["Texture"] = "Textur",
    ["Threat Plates"] = "Threat Plates",
    ["Tire son bandeau pour la déplacer : elle s'ouvrira ensuite toujours à cet endroit."] = "Zieh seinen Titelbalken zum Verschieben: Es öffnet sich danach immer an dieser Stelle.",
    ["Titre : %s"] = "Titel: %s",
    ["Ton mode"] = "Dein Modus",
    ["Ton niveau"] = "Deine Stufe",
    ["Ton nom apparaît en jaune dans le message, un petit son est joué (au plus toutes les 3 secondes) et l'icône du jeu clignote dans la barre des tâches si tu es sur une autre fenêtre. Les chuchotements ont déjà leur son dans le jeu."] = "Dein Name erscheint gelb in der Nachricht, ein kleiner Ton wird gespielt (höchstens alle 3 Sekunden) und das Spielsymbol blinkt in der Taskleiste, wenn du in einem anderen Fenster bist. Flüsternachrichten haben ihren Ton schon im Spiel.",
    ["Ton nom surligné, avec un son"] = "Dein Name hervorgehoben, mit Ton",
    ["Ton prix"] = "Dein Preis",
    ["Ton prix = le moins cher des autres vendeurs, moins ce montant en pièces de cuivre (au moins 1 pc de moins, pour passer devant). Si le moins cher est déjà à toi, tu t'alignes dessus au lieu de te concurrencer."] = "Dein Preis = der günstigste der anderen Verkäufer minus diesen Betrag in Kupfer (mindestens 1 K weniger, um vorne zu liegen). Gehört der günstigste schon dir, gleichst du dich an, statt zu konkurrieren.",
    ["Ton raccourci vers tout Platyplus, posé où tu veux à l'écran."] = "Deine Verknüpfung zu ganz Platyplus, platziert, wo du willst auf dem Bildschirm.",
    ["Ton équipement est réparé dès que tu parles à un marchand qui sait réparer."] = "Deine Ausrüstung wird repariert, sobald du mit einem Händler sprichst, der reparieren kann.",
    ["Ton équipement est réparé, avec l'argent de la guilde quand c'est possible."] = "Deine Ausrüstung wird repariert, wenn möglich mit dem Geld der Gilde.",
    ["Total des composants"] = "Gesamtkosten der Komponenten",
    ["Total estimé : %s"] = "Geschätzte Summe: %s",
    ["Total pour %d"] = "Summe für %d",
    ["Touche : %s"] = "Taste: %s",
    ["Touche d'interaction"] = "Interaktionstaste",
    ["Touche de mise en vente"] = "Einstelltaste",
    ["Touche pour boire"] = "Taste zum Trinken",
    ["Touche pour manger"] = "Taste zum Essen",
    ["Toujours vendre"] = "Immer verkaufen",
    ["Toujours vendre : %d"] = "Immer verkaufen: %d",
    ["Tous les mobs en combat avec ton groupe, et qui les tient."] = "Alle Gegner im Kampf mit deiner Gruppe und wer sie hält.",
    ["Tous les réglages dans l'onglet"] = "Alle Einstellungen im Reiter",
    ["Tous les réglages dans les onglets"] = "Alle Einstellungen in den Reitern",
    ["Tous tes mobs sont tenus."] = "Alle deine Gegner werden gehalten.",
    ["Tous tes sacs dans une seule fenêtre Platyplus, avec recherche, tri, argent et places libres."] = "Alle deine Taschen in einem einzigen Platyplus-Fenster, mit Suche, Sortierung, Geld und freien Plätzen.",
    ["Tous tes sacs dans une seule fenêtre."] = "Alle deine Taschen in einem einzigen Fenster.",
    ["Tout allumé, avec les automatismes : invitations, invocations, courrier…"] = "Alles an, samt Automatiken: Einladungen, Beschwörungen, Post…",
    ["Tout appliquer"] = "Alles anwenden",
    ["Tout cocher"] = "Alle anhaken",
    ["Tout coupé sauf l'icône : tu allumes seulement ce que tu veux."] = "Alles aus außer dem Symbol: Du schaltest nur ein, was du willst.",
    ["Tout décocher"] = "Alle abhaken",
    ["Tout est prêt !"] = "Alles ist bereit!",
    ["Tout est ramassé d'un coup, et tu vois ce que tu gagnes sans ouvrir tes sacs."] = "Alles wird auf einmal eingesammelt, und du siehst, was du erhältst, ohne deine Taschen zu öffnen.",
    ["Tout est ramassé dès l'ouverture, sans fenêtre de butin."] = "Alles wird beim Öffnen aufgesammelt, ohne Beutefenster.",
    ["Tout le contenu d'un cadavre ou d'un coffre est ramassé dès l'ouverture."] = "Der gesamte Inhalt einer Leiche oder Truhe wird beim Öffnen eingesammelt.",
    ["Tout le monde a passé"] = "Alle haben gepasst",
    ["Tout remettre par défaut"] = "Alles auf Standard zurücksetzen",
    ["Tout réinitialiser"] = "Alles zurücksetzen",
    ["Tout réinitialiser (garder mes listes)"] = "Alles zurücksetzen (meine Listen behalten)",
    ["Tout se règle avec /pp"] = "Alles wird mit /pp eingestellt",
    ["Tout sort que le jeu entoure d'une lueur sur tes barres : c'est le cas des procs des autres classes."] = "Jeder Zauber, den das Spiel auf deinen Leisten mit einem Leuchten umgibt: Das ist bei den Procs anderer Klassen der Fall.",
    ["Tout va bien"] = "Alles in Ordnung",
    ["Toutes les fonctions sont coupées, sauf l'icône Platyplus qui ouvre les options. Le jeu redevient presque comme sans l'addon ; allume ensuite ce que tu veux, onglet par onglet."] = "Alle Funktionen sind aus, außer dem Platyplus-Symbol, das die Optionen öffnet. Das Spiel ist fast wie ohne das Addon; schalte danach ein, was du willst, Reiter für Reiter.",
    ["Toutes tes quêtes sont faites (%d)"] = "Alle deine Quests sind abgeschlossen (%d)",
    ["Traducteur"] = "Übersetzer",
    ["Traduit le chat des joueurs étrangers avec une petite IA qui tourne sur ton PC (programme « Traducteur Platyplus », à lancer à côté du jeu)."] = "Übersetzt den Chat fremdsprachiger Spieler mit einer kleinen KI, die auf deinem PC läuft (Programm „Platyplus-Übersetzer“, neben dem Spiel zu starten).",
    ["Trier les sacs"] = "Taschen sortieren",
    ["Très rond"] = "Sehr rund",
    ["Tu n'as choisi personne à la main."] = "Du hast niemanden von Hand gewählt.",
    ["Tu pourras choisir un de ces objets :"] = "Du kannst einen dieser Gegenstände wählen:",
    ["Tu recevras :"] = "Du erhältst:",
    ["Tu recevras aussi :"] = "Du erhältst außerdem:",
    ["Un ! jaune pour un mob à tuer, un sac pour un mob qui laisse un objet de quête, avec ta progression. Disparaît quand l'objectif est fini. Les objectifs de tes équipiers sont ignorés."] = "Ein gelbes ! für einen zu tötenden Gegner, eine Tasche für einen Gegner, der einen Questgegenstand hinterlässt, mit deinem Fortschritt. Verschwindet, wenn das Ziel erreicht ist. Die Ziele deiner Mitspieler werden ignoriert.",
    ["Un 2e /roll du même joueur pour le même objet est signalé et ne compte pas. Une égalité au plus haut dé est signalée."] = "Ein 2. /roll desselben Spielers für denselben Gegenstand wird gemeldet und zählt nicht. Ein Gleichstand beim höchsten Wurf wird gemeldet.",
    ["Un add-on n'a ni Internet ni IA : la traduction est faite par le programme Traducteur Platyplus (dossier Platyplus\\Traducteur), qui s'affiche par-dessus le jeu. Clic sur [FR] : une fine bande de couleurs apparaît une demi-seconde en haut à gauche de l'écran, le programme la lit et traduit. Clic droit sur [FR] : le message dans une zone à copier (Ctrl+C), si la bande ne passe pas. Dans le jeu, Ctrl+Entrée ouvre une zone où tu écris en français : la traduction est copiée, colle-la dans le chat avec Ctrl+V. Pas de lien sur les messages protégés par le jeu (en instance)."] = "Ein Addon hat weder Internet noch KI: Die Übersetzung erledigt das Programm Platyplus-Übersetzer (Ordner Platyplus\\Traducteur), das über dem Spiel angezeigt wird. Klick auf [FR]: Ein feiner Farbstreifen erscheint eine halbe Sekunde oben links auf dem Bildschirm, das Programm liest ihn und übersetzt. Rechtsklick auf [FR]: die Nachricht in einem Feld zum Kopieren (Strg+C), falls der Streifen nicht durchkommt. Im Spiel öffnet Strg+Eingabe ein Feld, in dem du auf Französisch schreibst: Die Übersetzung wird kopiert, füge sie mit Strg+V in den Chat ein. Kein Link bei vom Spiel geschützten Nachrichten (in Instanzen).",
    ["Un autre joueur l'a touché en premier : pas d'XP ni de butin pour toi."] = "Ein anderer Spieler hat ihn zuerst getroffen: keine EP und keine Beute für dich.",
    ["Un bandeau au milieu de l'écran te signale que la touche utilisera l'objet de quête. Éteint, la touche marche pareil, sans rien afficher."] = "Ein Banner in der Bildschirmmitte zeigt dir an, dass die Taste den Questgegenstand benutzt. Ausgeschaltet funktioniert die Taste genauso, ohne etwas anzuzeigen.",
    ["Un cadavre qui a encore du butin pour toi brille à l'approche."] = "Eine Leiche, die noch Beute für dich hat, glänzt bei der Annäherung.",
    ["Un chat plus beau, plus lisible, qui se souvient, sans spam."] = "Ein schönerer, lesbarerer Chat, der sich erinnert, ohne Spam.",
    ["Un chat plus lisible : onglets, anti-spam, et l'historique gardé après un /reload."] = "Ein besser lesbarer Chat: Reiter, Spam-Schutz und der Verlauf bleibt nach einem /reload erhalten.",
    ["Un clic ouvre le lien, prêt à copier (Ctrl+C)."] = "Ein Klick öffnet den Link, bereit zum Kopieren (Strg+C).",
    ["Un clic règle toutes les fonctions d'un coup. Tu ajustes ensuite ce que tu veux, ici ou avec /pp."] = "Ein Klick stellt alle Funktionen auf einmal ein. Danach passt du an, was du willst, hier oder mit /pp.",
    ["Un mob qui t'attaquera si tu t'approches."] = "Ein Gegner, der dich angreifen wird, wenn du dich näherst.",
    ["Un mode allume ou coupe toutes les fonctions d'un coup : une base, que tu ajustes ensuite dans les autres onglets. Survole un mode pour voir exactement ce qu'il change."] = "Ein Modus schaltet alle Funktionen auf einmal ein oder aus: eine Grundlage, die du danach in den anderen Reitern anpasst. Fahr über einen Modus, um genau zu sehen, was er ändert.",
    ["Un mode ne change pas ta touche d'interaction, tes listes (« Ne jamais vendre », sorts ajoutés…), les positions, les tailles, les couleurs ni les réglages du jeu."] = "Ein Modus ändert weder deine Interaktionstaste noch deine Listen („Nie verkaufen“, hinzugefügte Zauber…), Positionen, Größen, Farben oder Spieleinstellungen.",
    ["Un mode pour commencer"] = "Ein Modus zum Start",
    ["Un panneau à droite de la fenêtre de l'HDV."] = "Ein Panel rechts vom Auktionshaus-Fenster.",
    ["Un petit « tic » quand une alerte apparaît."] = "Ein kleines „Tick“, wenn eine Warnung erscheint.",
    ["Un réglage que ton client ne connaît pas est grisé."] = "Eine Einstellung, die dein Client nicht kennt, ist ausgegraut.",
    ["Un son discret à chaque nouvelle alerte, au plus un par seconde. Exemple : Fulgurance devient prête, tu l'entends sans regarder. Le bouton Aperçu le joue aussi."] = "Ein dezenter Ton bei jeder neuen Warnung, höchstens einer pro Sekunde. Beispiel: Überwältigen wird bereit, du hörst es, ohne hinzusehen. Die Schaltfläche Vorschau spielt ihn auch ab.",
    ["Un son quand ta cible commence un sort que tu peux interrompre (au plus une fois par seconde)."] = "Ein Ton, wenn dein Ziel einen Zauber beginnt, den du unterbrechen kannst (höchstens einmal pro Sekunde).",
    ["Un sort ajouté ici est annoncé dès qu'il est sur une de tes barres, utilisable et hors recharge, comme un sort réactif. Exemple : ajoute Coup de bouclier pour voir son icône et sa touche chaque fois qu'il est prêt. Glisse le sort depuis ton grimoire, ou tape son nom. En combat, si le jeu cache la recharge, un sort ajouté peut rester affiché pendant sa recharge."] = "Ein hier hinzugefügter Zauber wird angezeigt, sobald er auf einer deiner Leisten liegt, einsetzbar ist und keine Abklingzeit hat, wie ein reaktiver Zauber. Beispiel: Füge Schildschlag hinzu, um sein Symbol und seine Taste zu sehen, wann immer er bereit ist. Zieh den Zauber aus deinem Zauberbuch oder tippe seinen Namen. Wenn das Spiel im Kampf die Abklingzeit verbirgt, kann ein hinzugefügter Zauber während seiner Abklingzeit angezeigt bleiben.",
    ["Un sort ignoré n'a jamais d'alerte, même s'il brille. Exemple : un sort qui brille tout le temps et t'encombre l'écran : ajoute-le ici. Tous les rangs du sort sont ignorés (reconnus par leur nom)."] = "Ein ignorierter Zauber löst nie eine Warnung aus, auch wenn er leuchtet. Beispiel: Ein Zauber, der ständig leuchtet und deinen Bildschirm überlädt: Füge ihn hier hinzu. Alle Ränge des Zaubers werden ignoriert (am Namen erkannt).",
    ["Un souci ? Tape /pp etincelles : il montre ce que Platyplus voit autour de toi."] = "Ein Problem? Tippe /pp etincelles: Es zeigt, was Platyplus um dich herum sieht.",
    ["Un souci, une idée ? Écris-nous sur github.com/bloufed/Platyplus."] = "Ein Problem, eine Idee? Schreib uns auf github.com/bloufed/Platyplus.",
    ["Une barre de mana pour le soigneur de ton groupe, posée où tu veux à l'écran : son nom et « 4 320 / 6 800 »."] = "Eine Manaleiste für den Heiler deiner Gruppe, platziert, wo du willst auf dem Bildschirm: sein Name und „4.320 / 6.800“.",
    ["Une barre qui se remplit jusqu'à ton prochain coup automatique. Visible en combat seulement."] = "Eine Leiste, die sich bis zu deinem nächsten automatischen Schlag füllt. Nur im Kampf sichtbar.",
    ["Une base de réglages en un clic : Recommandé, Complet, Immersif ou Minimal."] = "Eine Grundeinstellung mit einem Klick: Empfohlen, Komplett, Immersiv oder Minimal.",
    ["Une colonne collée au journal, avec tous les donjons dans l'ordre des niveaux : un clic ouvre un donjon, depuis n'importe quelle page. La tranche de niveau est en couleur selon ton niveau (vert : à ton niveau, or : bientôt, rouge : trop dur, gris : dépassé), et à droite tes quêtes faites (par exemple 2/7, ✓ quand tout est fait). « Accueil » ramène aux grandes cartes."] = "Eine am Journal haftende Spalte mit allen Dungeons in Stufenreihenfolge: Ein Klick öffnet einen Dungeon, von jeder Seite aus. Der Stufenabschnitt ist je nach deiner Stufe gefärbt (grün: auf deiner Stufe, gold: bald, rot: zu schwer, grau: überholt), und rechts deine erledigten Quests (zum Beispiel 2/7, ✓ wenn alles erledigt ist). „Startseite“ führt zu den großen Karten zurück.",
    ["Une couleur à part quand un autre tank du groupe tient le mob."] = "Eine eigene Farbe, wenn ein anderer Tank der Gruppe den Gegner hält.",
    ["Une fine barre en dessous si tu as deux armes."] = "Eine feine Leiste darunter, wenn du zwei Waffen hast.",
    ["Une icône posée où tu veux à l'écran (hors minicarte). Clic gauche : cette fenêtre. Clic droit : un menu pour allumer ou couper les fonctions. Glisse-la pour la déplacer."] = "Ein Symbol, platziert, wo du willst auf dem Bildschirm (nicht an der Minikarte). Linksklick: dieses Fenster. Rechtsklick: ein Menü zum Ein- und Ausschalten der Funktionen. Zieh es, um es zu verschieben.",
    ["Une ligne par mob : nom, vie, qui le tient, ta menace. Vert : tu l'as, orange : tu le perds, rouge : tu ne l'as plus, bleu : un autre tank le tient, gris : il n'a pas de cible. DPS : rouge = il te tape (compteur « N sur toi »)."] = "Eine Zeile pro Gegner: Name, Leben, wer ihn hält, deine Bedrohung. Grün: du hast ihn, orange: du verlierst ihn, rot: du hast ihn nicht mehr, blau: ein anderer Tank hält ihn, grau: er hat kein Ziel. Schaden: rot = er greift dich an (Zähler „N auf dir“).",
    ["Une ligne « HDV » sur les objets : sacs, équipement porté, liens..."] = "Eine Zeile „AH“ auf Gegenständen: Taschen, getragene Ausrüstung, Links ...",
    ["Une liste « Ne jamais vendre » protège ce que tu veux garder, et un aperçu montre ce qui partira."] = "Eine Liste „Nie verkaufen“ schützt, was du behalten willst, und eine Vorschau zeigt, was verkauft wird.",
    ["Une mise en vente par clic"] = "Ein Einstellen pro Klick",
    ["Une petite icône à droite des alertes tant que tu as le buff Maîtrise du blocage."] = "Ein kleines Symbol rechts von den Warnungen, solange du den Buff Schildblock hast.",
    ["Une pierre de soins"] = "Ein Heilstein",
    ["Une pièce n'est vendue que si son niveau d'objet est inférieur d'au moins ce nombre de points à celui de la pièce équivalente que tu portes."] = "Ein Teil wird nur verkauft, wenn seine Gegenstandsstufe um mindestens so viele Punkte unter der des entsprechenden Teils liegt, das du trägst.",
    ["Une plante à cueillir scintille quand tu t'en approches, terne de loin, vive à portée, grise si ta compétence est trop basse. Un seul objet brille à la fois. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Eine zu pflückende Pflanze funkelt, wenn du dich näherst: matt aus der Ferne, hell in Reichweite, grau, wenn deine Fertigkeit zu niedrig ist. Es glänzt immer nur ein Objekt. Nutzt das Interaktionsziel des Spiels: das nächste Objekt, bis etwa 15 m, rund um dich. Dafür schaltet Platyplus „Interaktionstaste aktivieren“ und die Interaktionssymbole der Weltobjekte des Spiels ein und stellt sie wie zuvor wieder her, wenn du alle Funken unten ausschaltest. Kein Funke während eines Kampfes.",
    ["Une seule fenêtre pour tous les sacs"] = "Ein einziges Fenster für alle Taschen",
    ["Une seule touche pour tout : PNJ, coffres, plantes, cadavres à dépouiller, dialogues et quêtes."] = "Eine einzige Taste für alles: NPCs, Truhen, Pflanzen, Leichen zum Häuten, Dialoge und Quests.",
    ["Une touche pour interagir, parler et rendre les quêtes ; deux pour manger et boire."] = "Eine Taste zum Interagieren, Sprechen und Abgeben von Quests; zwei zum Essen und Trinken.",
    ["Une touche pour parler aux PNJ, ramasser le butin et rendre les quêtes ; des alertes de combat, la menace lisible sur les mobs, la vente automatique, des fenêtres plus claires et bien plus. Tous les réglages sont dans la fenêtre de Platyplus (tu peux aussi taper /pp)."] = "Eine Taste, um mit NSCs zu sprechen, Beute einzusammeln und Quests abzugeben; Kampfwarnungen, lesbare Bedrohung auf den Gegnern, automatischer Verkauf, übersichtlichere Fenster und vieles mehr. Alle Einstellungen findest du im Platyplus-Fenster (du kannst auch /pp tippen).",
    ["Une touche pour presque tout"] = "Eine Taste für fast alles",
    ["Utiliser l'objet de quête au bon endroit"] = "Questgegenstand am richtigen Ort benutzen",
    ["Utiliser la fenêtre de chat Platyplus"] = "Platyplus-Chatfenster benutzen",
    ["Utiliser la fenêtre de quête Platyplus"] = "Platyplus-Questfenster benutzen",
    ["Utiliser la fenêtre du personnage Platyplus"] = "Platyplus-Charakterfenster benutzen",
    ["Utiliser les sacs Platyplus"] = "Platyplus-Taschen benutzen",
    ["Valide automatiquement la fenêtre de confirmation de Blizzard quand tu ramasses un objet qui se lie à toi. Tu ne verras plus cette question."] = "Bestätigt automatisch das Bestätigungsfenster von Blizzard, wenn du einen Gegenstand plünderst, der sich an dich bindet. Du siehst diese Frage nicht mehr.",
    ["Valider les quêtes et les dialogues"] = "Quests und Dialoge bestätigen",
    ["Vend aussi les pièces d'équipement nettement moins bonnes que ce que tu portes déjà, selon les réglages ci-dessous. Les objets de « Ne jamais vendre » sont toujours épargnés. Vérifie d'abord avec l'aperçu en bas de page."] = "Verkauft auch Ausrüstungsteile, die deutlich schlechter sind als das, was du schon trägst, gemäß den Einstellungen unten. Gegenstände aus „Nie verkaufen“ bleiben immer verschont. Prüfe zuerst mit der Vorschau am Seitenende.",
    ["Vend aussi les pièces « lié quand équipé » qui ne sont pas encore liées à toi. Elles peuvent parfois se vendre plus cher à l'hôtel des ventes, donc c'est coupé par défaut."] = "Verkauft auch „Beim Anlegen gebunden“-Teile, die noch nicht an dich gebunden sind. Sie lassen sich manchmal im Auktionshaus teurer verkaufen, daher ist dies standardmäßig aus.",
    ["Vend tous les objets de qualité médiocre (gris) de tes sacs dès que tu ouvres un marchand."] = "Verkauft alle Gegenstände schlechter (grauer) Qualität aus deinen Taschen, sobald du einen Händler öffnest.",
    ["Vend tout de suite ce qui est listé. Un marchand doit être ouvert."] = "Verkauft sofort, was aufgelistet ist. Ein Händler muss geöffnet sein.",
    ["Vendre"] = "Verkaufen",
