    ["Version"] = "Version",
    ["Vert : tout va bien, orange : ça se joue, rouge : danger. Les couleurs suivent ton rôle (tank ou DPS)."] = "Grün: alles in Ordnung, orange: es ist knapp, rot: Gefahr. Die Farben folgen deiner Rolle (Tank oder DPS).",
